(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c34"]=[{"id":"00011509","register_sub_id":"101","register_pk":"210537","name":"蓮教寺書院","kana":"れんきょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15659889,"lng":137.01203,"geo_status":"db","era":"文化9年（1812）／昭和30年頃・平成27年改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0472","desc":"本堂背面に廊下を介して接続する。桁行七間半、梁間六間半、切妻造、桟瓦葺。平面は東西二列に各三室を並べる六間取で、東西両側に広縁を設け、西面南端には玄関を付ける。上段の間は付書院を備え、天井は格天井とするなど、高い格式を備えた上質な書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011509"},{"id":"00011511","register_sub_id":"101","register_pk":"210539","name":"蓮教寺鐘楼","kana":"れんきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15635111,"lng":137.01158111,"geo_status":"db","era":"明治15年","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"23-0474","desc":"山門の西側に東西棟で建つ。桁行一間梁間一間、入母屋造本瓦葺の鐘楼。玉石積みの基壇上に丸柱を四方転びに立て、腰貫、内法貫を入れ、虹梁状の頭貫と台輪で固める。天井は折上小組格天井で、軒は二軒扇垂木。妻飾には亀の彫刻が施され、華やかな意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011511"},{"id":"00011508","register_sub_id":"101","register_pk":"210536","name":"蓮教寺本堂","kana":"れんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15647306,"lng":137.01187889,"geo_status":"db","era":"宝暦8年（1758）／宝暦14年（1764）・文化9年（1812）増築、平成16年改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡、太鼓楼付","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0471","desc":"市東部の丘陵地にある真宗高田派寺院本堂。桁行五間、梁間五間、寄棟造本瓦葺で、南面し向拝一間を付ける。鼓楼付の玄関、両側面後方下屋は後の増築である。内部は外陣、矢来内と続き、奥に内陣と両脇に余間を配し、後堂を設ける典型的な真宗本堂平面で上質な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011508"},{"id":"00009615","register_sub_id":"101","register_pk":"194611","name":"蓮慶寺大門","kana":"れんけいじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1他","lat":34.91634777,"lng":136.91936928,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0379","desc":"境内の南東隅に位置し、本堂正面に東面して建つ四脚門。切妻造本瓦葺、二軒繁垂木。本柱を円柱、控柱を几帳面取角柱とし、石製礎盤上に建つ。格天井を張り、組物は実肘木拳鼻付平三斗の詰組、妻は二重虹梁で上段に笈形付大瓶束を立てる。規模壮大で質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009615"},{"id":"00009616","register_sub_id":"101","register_pk":"194612","name":"蓮慶寺土塀","kana":"れんけいじどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1他","lat":34.91642564,"lng":136.91942273,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、瓦葺、総延長17m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0380","desc":"境内の南東隅、大門の南北両脇に矩折れに接続する脇塀及び土塀からなる。布石積基礎を高く積み、脇塀は南北各二間、切妻造桟瓦葺とし、土塀は東へ各四間、東西棟切妻造桟瓦葺で、いずれも腰下竪板張、上部漆喰塗である。大門とともに境内正面の意匠を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009616"},{"id":"00009614","register_sub_id":"101","register_pk":"194610","name":"蓮慶寺本堂","kana":"れんけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1","lat":34.91641915,"lng":136.91887555,"geo_status":"db","era":"文化8","year":1811,"year_source":"db","year_min":1811,"year_max":1811,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積538㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0378","desc":"境内南西隅に東面して建つ。桁行九間梁間八間半、入母屋造本瓦葺で、向拝三間を付ける。前方を外陣、後方を内陣及び余間と飛檐の間とし、外陣三方を広縁及び切り目縁で囲み、背面に後堂がつく。内陣を上々段、二重折上格天井とし、格調高い大規模な真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009614"},{"id":"00014246","register_sub_id":"101","register_pk":"509636","name":"恵日山観音寺観音堂","kana":"えにちざんかんのんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和後","pref":"三重県","address":"三重県津市大門447","lat":34.72066389,"lng":136.51322222,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積305㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0313","desc":"津城下中心部に位置し、津観音で知られる寺院本堂。戦災焼失した旧国宝本堂を建築史家村田治郎により復元。鉄筋コンクリート造寄棟造本瓦葺の五間堂で、正面に向拝を付け、四周に縁を廻す。出三斗や蓑束、建具等外廻り意匠によく旧態を伝える復興建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014246"},{"id":"00015467","register_sub_id":"101","register_pk":"533482","name":"大村神社本殿","kana":"おおむらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市阿保1555","lat":34.67034167,"lng":136.18373056,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0336","desc":"重文大村神社宝殿の東脇に北面して建つ本殿。正面一間、背面三間、側面二間の入母屋造妻入檜皮葺で正面に向拝を付し、周囲に刎高欄付縁を廻らす。身舎は円柱上に三斗を組み、軒は二軒繁垂木。内陣正面三箇所は幣軸構え。入母屋造の屋根が宝殿と呼応する社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015467"},{"id":"00009777","register_sub_id":"101","register_pk":"195606","name":"開化寺観音堂","kana":"かいかじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.7707066,"lng":136.12206276,"geo_status":"db","era":"江戸後期／明治22・昭和11移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0162","desc":"境内南東に西面して建つ。桁行四間梁間三間、入母屋造妻入、本瓦葺で、向拝三間を付ける。堂内は前寄り一間を広縁とし、後方三間を内陣とする。内陣奥に仏壇を設けて厨子を安置する。仏壇や向拝周りなどの細部意匠を凝らし、時代的特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009777"},{"id":"00009778","register_sub_id":"101","register_pk":"195607","name":"開化寺三重塔","kana":"かいかじさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.77067805,"lng":136.12180102,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積4.0㎡","structure_material":"木造三重塔","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0163","desc":"境内南西に、東面して建つ。木造三間三重塔、本瓦葺で、総高一一メートルを測る。初重は繁垂木で中備蟇股、二重は扇垂木で同蓑束、三重は板軒として組物や軒裏などを雲紋彫刻で満たすなど、各重ごとに異なる意匠が特徴。県下では希少な三重塔の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009778"},{"id":"00009779","register_sub_id":"101","register_pk":"195608","name":"開化寺門","kana":"かいかじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.77061856,"lng":136.12190096,"geo_status":"db","era":"江戸末期／明治期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0164","desc":"境内南入口に構える薬医門である。梁で持出した虹梁上の出組組物でさらに丸桁を持出し、軒を深める。虹梁上には彫刻化した蟇股をおき、背面では二重虹梁の各段に同様の蟇股を千鳥に配する。また妻飾大瓶束の笈型なども立体的な彫刻を多用する装飾性豊かな門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009779"},{"id":"00013259","register_sub_id":"101","register_pk":"366248","name":"西方寺木枯亭","kana":"さいほうじこがらしてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県鈴鹿市寺家三丁目2904","lat":34.82400278,"lng":136.58131667,"geo_status":"db","era":"明治前期／昭和40年頃・平成24年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0274","desc":"市東部の伊勢湾沿岸に位置し、境内東寄りに建つ本堂の西側に接続し南面して建つ。木造平屋建、切妻造桟瓦葺で、正面本堂寄りに式台玄関を突出する。内部正面側に鞘の間、奥は二列に二室ずつ配し、西側二室には床、棚を備えるなど、境内を構成する上質な書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013259"},{"id":"00008708","register_sub_id":"101","register_pk":"149429","name":"寂照寺観音堂","kana":"じゃくしょうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.47698385,"lng":136.72128367,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0106","desc":"金毘羅堂の南に西面して建つ。入母屋造妻入本瓦葺で、正面に1間向拝を付ける。正面4.8ｍ奥行7.7ｍ。外壁を漆喰の大壁とし、土蔵風に造る。内部は畳敷で、棹縁天井、背面に接して仏壇を設ける。金毘羅堂と並び建ち、伽藍景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008708"},{"id":"00008707","register_sub_id":"101","register_pk":"149428","name":"寂照寺金毘羅堂","kana":"じゃくしょうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.4770473,"lng":136.72137066,"geo_status":"db","era":"天保10年(1839)","year":1839,"year_source":"converted","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0105","desc":"旧伊勢街道東に占める境内の東に位置する。桁行3間梁間3間の入母屋造妻入本瓦葺。乱積基壇上に建ち、柱は正面のみ円柱。平三斗、一軒半繁垂木。内部は板床で、背面1間通りに壇を構える。周囲棹縁で、中央の鏡天井に龍を描く。幕末における小仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008707"},{"id":"00008709","register_sub_id":"101","register_pk":"149430","name":"寂照寺山門","kana":"じゃくしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.47721116,"lng":136.72107452,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0107","desc":"金毘羅堂の西方に位置する。1間1戸薬医門、切妻造本瓦葺。本柱間を冠木、本・控柱間に女梁に支持させた男梁や貫、控柱間は虹梁と桁で固める。妻は笈形付大瓶束とし、軒は一軒疎垂木。鰭付三花懸魚。装飾を排し、欅の良材を用いた手堅い仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008709"},{"id":"00009621","register_sub_id":"101","register_pk":"194617","name":"寿量寺旧大黒殿","kana":"じゅりょうじきゅうだいこくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県桑名市大字桑名字伝馬町2363","lat":35.05764843,"lng":136.6902871,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積16㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0154","desc":"東海道に東面する境内の北方に南面する。桁行四・四メートル梁間二・九メートル、ヴォールト状の屋根をかける鉄筋コンクリート造で妻入とする。正面向拝では、フルーティングを施した角柱に枠肘木を置いて唐破風屋根を受ける。近代和風建築として特異な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009621"},{"id":"00009622","register_sub_id":"101","register_pk":"194618","name":"寿量寺鐘楼","kana":"じゅりょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県桑名市大字桑名字伝馬町2363","lat":35.05749376,"lng":136.69019668,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造、面積7.5㎡","structure_material":"鉄筋コンクリート造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0155","desc":"境内南方に建つ。方一間、宝形造鉄筋コンクリート造。柱間上部をアーチで繋ぎ、洗い出して文様をつける。伝統的な鐘楼の形態を基調とし、簡略化された和風の意匠とアーチとの折衷を試みた、当地域での鉄筋コンクリート技術を知る上で欠くことのできない建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009622"},{"id":"00008706","register_sub_id":"101","register_pk":"149427","name":"誓元寺山門","kana":"せいがんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96055465,"lng":136.60699563,"geo_status":"db","era":"明治45年","year":1912,"year_source":"converted","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0104","desc":"境内東辺中央に位置する。間口3.1ｍの四脚門で、両脇に袖塀を付け、潜りを開ける。切妻造本瓦葺。本柱が円柱、控柱が方柱で、礎盤上にたつ。支輪付出組、二軒繁垂木。冠木と楣間には彫刻を飾り、桟唐戸を装置。本格的な仕様で、風格ある伽藍正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008706"},{"id":"00008705","register_sub_id":"101","register_pk":"149426","name":"誓元寺鐘楼","kana":"せいげんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96046506,"lng":136.60688216,"geo_status":"db","era":"明治45年","year":1912,"year_source":"converted","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積48㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0103","desc":"境内の東南、高い玉石の亀甲積基壇上に建つ。方1間吹放ちとする鐘楼。礎盤上に円柱を内転びにたて、貫や台輪で固め、支輪付出組を組む。柱間中央にも出組を置き、その間に蟇股を飾る。二軒繁垂木。入母屋造桟瓦葺。高度な石積技術や堅実な木工技能がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008705"},{"id":"00009980","register_sub_id":"101","register_pk":"196127","name":"中山寺経蔵","kana":"ちゅうざんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47785769,"lng":136.70855653,"geo_status":"db","era":"元禄15／平成18改修","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0170","desc":"本堂の南方に東面して建つ。土蔵造平屋建、宝形造桟瓦葺の経蔵。正面に一間向拝を付け、向拝以外の軒裏を塗り込めて防火性を高める。内周の棚に教典を納め、厨子には観音像を祀る。内部は床を張って鏡天井とする。堅牢な外観の経蔵で、境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009980"},{"id":"00009981","register_sub_id":"101","register_pk":"196128","name":"中山寺山門","kana":"ちゅうざんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47773366,"lng":136.70897643,"geo_status":"db","era":"元禄12頃／平成18改修","year":1699,"year_source":"db","year_min":1699,"year_max":1699,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0171","desc":"境内の東辺に開く。一間一戸の薬医門で、角柱の本柱上に太い冠木を置き、男梁を載せ、屋根は切妻造本瓦葺とする。本柱からは腕木状に女梁を伸ばし、斗を置いて男梁を支える。妻飾は棟束に板蟇股様の笈形を付ける。全体に装飾を控えて、簡明で重厚な意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009981"},{"id":"00009979","register_sub_id":"101","register_pk":"196126","name":"中山寺本堂","kana":"ちゅうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47800939,"lng":136.70872142,"geo_status":"db","era":"明暦2／元文3・安政6改修","year":1656,"year_source":"db","year_min":1656,"year_max":1656,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積283㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0169","desc":"六間取方丈型の本堂で、室中の間口は三間半、上間と下間の間口を各二間、正側面に一間幅の広縁、背面に半間の廊下を廻す。正面の落縁を堂内に取り込む点は特徴的である。臨済宗寺院の方丈型本堂としての規式をよく留め、規模も大きい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009979"},{"id":"00016674","register_sub_id":"101","register_pk":"579158","name":"長慶寺庫裏","kana":"ちょうけいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市蔵持町里2565","lat":34.639498,"lng":136.104711,"geo_status":"db","era":"天明元年（1781）／江戸末期増築、昭和後期改修","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積237㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0344","desc":"本堂の北東に位置する庫裏。平屋建東西棟の切妻造桟瓦葺で、西に入母屋造の角屋を延ばし、南面中央に式台を構える。内部の東はかつての土間、西は前後７室を配し、南西の床構え付き座敷は庭に面して広縁を廻らす。床廻りの貼付壁など古刹の格式を示す庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016674"},{"id":"00016673","register_sub_id":"101","register_pk":"579157","name":"長慶寺本堂","kana":"ちょうけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市蔵持町里2565","lat":34.639366,"lng":136.104491,"geo_status":"db","era":"享保12年（1727）","year":1727,"year_source":"db","year_min":1727,"year_max":1727,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0343","desc":"市街地北西に位置する真言宗寺院の本堂。境内西側に東面して建つ一重入母屋造裳階付で正面に一間向拝を付す。軸部は円柱で組物は出三斗、軒は二軒繁垂木とする。内部は内・外陣、両脇陣からなり、内陣奥に須弥壇を構える。向拝の木鼻や中備蟇股など彫刻秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016673"},{"id":"00010829","register_sub_id":"101","register_pk":"201664","name":"片山寺土蔵","kana":"へんざんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県度会郡南伊勢町阿曽浦16","lat":34.276007,"lng":136.583706,"geo_status":"db","era":"文化4","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0230","desc":"境内西方の一段高い位置に南面して建つ二階建土蔵。切妻造、置屋根式桟瓦葺で正面出入口に下屋を張出し、東面二階に窓を開ける。外壁は簓子下見板張として、妻面は鉢巻のみ漆喰塗を表す。小規模ながら、入江を臨む独特な風致に築かれた庭園の一画を彩る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010829"},{"id":"00010828","register_sub_id":"101","register_pk":"201663","name":"片山寺本堂","kana":"へんざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県度会郡南伊勢町阿曽浦16","lat":34.275878,"lng":136.583861,"geo_status":"db","era":"延宝5／大正前期・平成2改修","year":1677,"year_source":"db","year_min":1677,"year_max":1677,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0229","desc":"阿曽浦集落の急峻地に構える境内に南面して建つ。平面は六間取の方丈形式で、仏間背面に眠蔵をもつなど古式を備える。軸部や内装は簡明ながら、屋根を本瓦葺として重厚な趣をもつ。地方禅院における江戸中期の方丈型本堂の好例であり、歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010828"},{"id":"00008128","register_sub_id":"101","register_pk":"132526","name":"三瀬谷神社本殿","kana":"みせだにじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県多気郡大台町佐原439","lat":34.39701196,"lng":136.40594746,"geo_status":"db","era":"元禄3年(1690)／大正3年移築","year":1690,"year_source":"db","year_min":1690,"year_max":1690,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"24 － 0088","desc":"東南に正面を向ける一間社。入母屋造銅板葺で、正面に千鳥破風と軒唐破風付向拝を付設する。三方に擬宝珠高欄付切目縁をまわし、正面に木階を付ける。円柱で、尾垂木付の二手先斗栱、中備蟇股。軒天井を張り、二軒繁垂木が深い軒を持ち出す。気品ある社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008128"},{"id":"00004365","register_sub_id":"101","register_pk":"105355","name":"妙華寺本堂","kana":"みょうげじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市久居二ノ町1743","lat":34.67263702,"lng":136.47324096,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積264㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"24 － 0051","desc":"真宗高田派寺院の本堂。桁行５間梁間６間半の主体部は，表側を大間，奥を中央内陣，両脇余間，後堂に区画し，両側面後方下屋を楽の間とする。向拝の装飾的な構成や，寄棟造，桟瓦葺の屋根を錣葺とする等特徴ある外観をもち，地域の歴史景観に欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004365"},{"id":"00002401","register_sub_id":"101","register_pk":"103391","name":"安養院阿弥陀堂","kana":"あんよういんあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07986721,"lng":135.86870759,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0170","desc":"西教寺の塔頭で，参道東端の総門と道路を隔てた位置にある。敷地西側の阿弥陀堂は乱石積基壇上に東面して建ち，入母屋造，桟瓦葺で，４周に切目縁を廻し，正面１間を広縁とする。禅宗寺院の方丈建築を意識しつつ，内部空間や細部の造形に近代的要素がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002401"},{"id":"00002409","register_sub_id":"101","register_pk":"103399","name":"安養院蔵","kana":"あんよういんくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07994817,"lng":135.86876448,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0178","desc":"阿弥陀堂の北側に並立して建つ。総２階建，寄棟造，桟瓦葺，妻入で，外壁は腰をモルタル塗，上部を漆喰塗とし，東面に銅板葺の庇を設ける。派手さはないが，東面の出入口廻りは漆喰で鳥居型につくり，内部の壁も幅広の縦板壁とするなど，技術的な質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002409"},{"id":"00002402","register_sub_id":"101","register_pk":"103392","name":"安養院庫裡","kana":"あんよういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.079742,"lng":135.868942,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0171","desc":"敷地のほぼ中央に，北面して建つ。入母屋造，妻入で，ゆったりとした桟瓦葺の大屋根を架け，４周に下屋庇を廻し，西側には切妻造の台所棟を連結する。側廻りは角柱に舟肘木をあげ，内部は均整のとれた比例で室内空間をつくり，欄間などの細部は繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002402"},{"id":"00002406","register_sub_id":"101","register_pk":"103396","name":"安養院地蔵堂","kana":"あんよういんじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.079636,"lng":135.86871069,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0175","desc":"庫裡南側に南面して建つ宝形造，桟瓦葺の小堂。部材の風蝕程度から，江戸末期頃の建築と思われる。内部は１室で，４周に軒支柱を立てて，背面を仏壇，左側面を物置にする。全体に質素であるが，正面は時代に相応しい豪華な彫刻欄間を設け，意匠を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002406"},{"id":"00002403","register_sub_id":"101","register_pk":"103393","name":"安養院書院","kana":"あんよういんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07956228,"lng":135.8688391,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0172","desc":"庫裡南側にあり，西南隅が聖天堂と接続する。入母屋造，桟瓦葺，妻入で，内部は床構えのある居室と炊事場からなり，庭に面した東と南に矩折れの廊下を設ける。規模は小さいが，床の構成や土壁の仕上げなど，趣がある瀟洒な室内意匠を備えた住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002403"},{"id":"00002407","register_sub_id":"101","register_pk":"103397","name":"安養院聖天堂","kana":"あんよういんしょうてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07951386,"lng":135.868729,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0176","desc":"天保期の絵図や，細部の様式から江戸後期と考えられ，安養院で最古の仏堂。内陣を核として，前面へ凸状の外陣を設け，右手に炊事場，左手には書院が接続する。土蔵造で宝形屋根の内陣と入母屋造の外陣などを巧みに処理した複雑で特異な形態の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002407"},{"id":"00002405","register_sub_id":"101","register_pk":"103395","name":"安養院弁天堂","kana":"あんよういんべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07970328,"lng":135.86858148,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0174","desc":"敷地西側のほぼ中央の小高い地に東面して建つ。方形平面で背面に仏壇部を張り出し，正面と両側面に擬宝珠高欄付の縁を廻し，軒は深くつくる。小規模だが，軸部を長押で固め，組物を三斗，建具を板扉と連子窓，内部を小組格天井とした正統的な和様の仏堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002405"},{"id":"00002404","register_sub_id":"101","register_pk":"103394","name":"安養院門","kana":"あんよういんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07992921,"lng":135.86893803,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0173","desc":"安養院は恵心僧都源信につらなる安養尼の遺跡の旧地と伝えるが，現在の建物は昭和初期に山口玄洞氏の寄付で再興された。敷地北側にある門は切妻造，桟瓦葺の１間１戸薬医門で，軒廻りや組物は簡素であるが，絵様細部は大柄で，堂々とした外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002404"},{"id":"00002408","register_sub_id":"101","register_pk":"103398","name":"安養院礼拝堂","kana":"あんよういんれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.0795448,"lng":135.868622,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0177","desc":"聖天堂西側にあり，渡廊下で連絡している。桁行３間，梁間２間，入母屋造，桟瓦葺の小規模な建物。角柱に舟肘木をあげて，桁を受ける。１軒疎垂木であるが，緩やかに反った軒をつくり，木連格子の妻飾や正面と両側面に設けた連子窓など，丁寧な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002408"},{"id":"00007751","register_sub_id":"101","register_pk":"108732","name":"ヴォーリズ記念病院礼拝堂","kana":"う゛ぉーりずきねんびょういんれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町480-1","lat":35.15235718,"lng":136.08910328,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡、石段及び渡廊下付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"25-0276","desc":"敷地北西の小高い位置に南面して建つ。木造平屋建、建築面積９７㎡、切妻造妻入桟瓦葺で、正面に石段、西方に渡廊下を付ける。玄関ホールの北に小屋組を現す単廊式礼拝堂、東に牧師室、西に控室と便所を配す。半円アーチを開ける白いモルタル壁が木立に映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007751"},{"id":"00003434","register_sub_id":"101","register_pk":"104424","name":"円寿院本堂","kana":"えんじゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南清水町150","lat":35.14320869,"lng":136.21604503,"geo_status":"db","era":"正徳元","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0224","desc":"集落西北にある浄土宗本堂。桁行３間，梁間４間，入母屋造，向拝１間で，軒は二軒繁垂木とする。梁間を前後に分け，前方を外陣，奥は中央に一段高く内陣を取り，左右に脇陣を配す。簡素な小堂だが，木太く，内外陣境の欄間や小壁の彫刻など入念な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003434"},{"id":"00000855","register_sub_id":"101","register_pk":"101845","name":"近江神宮神楽殿","kana":"おうみじんぐうかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03276349,"lng":135.85224025,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積162㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0077","desc":"正面三間奥行四間，東西棟の入母屋造建物で，東南端に切妻屋根の車寄玄関を張出し，廻廊側の正面に唐破風をつける。北面と西面に廊下を回し，北で参集所に，西で神饌所に連絡する。第二期工事分の核となる施設で，時節にもかかわらず上質に仕上げられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000855"},{"id":"00000854","register_sub_id":"101","register_pk":"101844","name":"近江神宮神楽殿廻廊","kana":"おうみじんぐうかぐらでんかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03269031,"lng":135.85246273,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積64㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0076","desc":"外院北部の北端に位置する神楽殿の前面をコの字型に囲う廊。外側を連子窓，内側を開放とし，桁行六間の東廊は虹梁中央の束上に化粧棟木を載せて南北棟の入母屋屋根を架け，各五間の北・南廊は海老虹梁により内外の柱を繋ぎ，内側柱筋に棟を上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000854"},{"id":"00000852","register_sub_id":"101","register_pk":"101842","name":"近江神宮北神門","kana":"おうみじんぐうきたしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03240635,"lng":135.85120396,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造八脚門，銅板葺，建築面積15㎡","structure_material":"木造八脚門","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0074","desc":"神楽殿に対応した門で，外院北部の入口にあたる。三間三戸の八脚門で，円形本柱と角形控柱の上部を海老虹梁で繋ぎ，本柱の上に平三斗を載せて化粧棟木を，控柱は大斗肘木で軒桁を支え，反り付きの切妻屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000852"},{"id":"00000838","register_sub_id":"101","register_pk":"101828","name":"近江神宮後門","kana":"おうみじんぐうこうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造棟門，檜皮葺，幅2.7m","structure_material":"木造棟門","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0060","desc":"本殿の真後ろ，内内院の西面を限る透塀の中央に位置する切妻造，檜皮葺の門で，扉に連子を入れて透塀との連続性を持たせながら，屋根を一段高くするとともに反りを緩やかに付けて透塀を分節している。中門と同様，内内院の重要な結界要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000838"},{"id":"00000864","register_sub_id":"101","register_pk":"101854","name":"近江神宮斎館","kana":"おうみじんぐうさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03336067,"lng":135.85286378,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積98㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0086","desc":"勅使玄関の北に接続する入母屋造の建物で，この棟のみ軸線を３０度程振る。８畳と床付１０畳の二間構成で，南と東の二面に畳敷の広縁を回し，東面に高欄付の縁をつける。８畳間は棹縁天井，１０畳の書院座敷は格天井とし，落着きある空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000864"},{"id":"00000865","register_sub_id":"101","register_pk":"101855","name":"近江神宮斎館玄関","kana":"おうみじんぐうさいかんげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03331676,"lng":135.85276132,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積27㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0087","desc":"斎館西面と社務所西棟の北端を結ぶ通路の中央部から北に突出させた切妻造，瓦葺の玄関。斎館の裏玄関にあたる。正面に縦長の桟唐戸を四枚建込み，長押上に細かい縦桟の欄間を入れる。舟肘木を用い，妻飾は豕叉首で，破風に簡素な懸魚をつけて立面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000865"},{"id":"00000858","register_sub_id":"101","register_pk":"101848","name":"近江神宮参集所","kana":"おうみじんぐうさんしゅうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03291864,"lng":135.85236612,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積155㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0080","desc":"神楽殿に接続し，神楽殿の北面崖際より北に伸びる一部二階建，瓦葺の南北棟建物で，１０畳間を四間並べ，北端東面に通用玄関を，西に参集所玄関への接続部を張りだす。１０畳四間は一室空間になり，南端に床の間を設け，東面は連続の出窓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000858"},{"id":"00000860","register_sub_id":"101","register_pk":"101850","name":"近江神宮参集所玄関","kana":"おうみじんぐうさんしゅうじょげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03310892,"lng":135.8523954,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺一部瓦葺，建築面積101㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0082","desc":"東西棟，入母屋造の建物で，南に登廊に接続する張出し部を，北に千鳥破風を頂く玄関車寄を突出させ，東面で社務所に連絡する。主屋部は真壁造で，腰を簓子下見とするが，玄関車寄は舟肘木を用いるなど正面に相応しい意匠でまとめあげられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000860"},{"id":"00000859","register_sub_id":"101","register_pk":"101849","name":"近江神宮参集所登廊","kana":"おうみじんぐうさんしゅうじょのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03301817,"lng":135.85238076,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺一部瓦葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0081","desc":"神饌所，神楽殿から参集所，社務所を経て北端の斎館までは登廊や廊下により結ばれているが，参集所登廊はそのほぼ中間に位置し，ここにのみ防火区画を設ける。階段中途の踊場に防火扉を設置し，防火壁を卯建状に立ち上げて上面に瓦を葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000859"},{"id":"00000867","register_sub_id":"101","register_pk":"101857","name":"近江神宮参拝者休憩所","kana":"おうみじんぐうさんぱいしゃきゅうけいじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.0312559,"lng":135.85252127,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積75㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0089","desc":"第二鳥居の左手後方に位置する。平屋建，瓦葺，切妻屋根の四周に庇を回す外観を呈する。内部は身舎部分を棹縁天井，庇部分は化粧小屋裏をあらわし，丸柱と差肘木により特徴ある架構を造る。節のある材を効果的に用いて味わいある内部空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000867"},{"id":"00000861","register_sub_id":"101","register_pk":"101851","name":"近江神宮社務所Ⅰ","kana":"おうみじんぐうしゃむしょいち","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03313527,"lng":135.8528023,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積246㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0083","desc":"ロの字型平面の東棟と南棟部分。東棟は南北棟の入母屋造建物で，東面の中央に唐破風の車寄を突出させて貴賓玄関とし，右手を応接間，左手を脇玄関・宮司室とする。棟を落とした南棟は，事務室を主とし，南面の中央に通用玄関を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000861"},{"id":"00000862","register_sub_id":"101","register_pk":"101852","name":"近江神宮社務所Ⅱ","kana":"おうみじんぐうしゃむしょに","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.0332026,"lng":135.85260909,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積175㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0084","desc":"ロの字型平面の北棟と西棟部分で，北棟は１０畳８畳の二間構成で斎館の付属館的性格をもち，西棟は炊事場・浴室等の棟で瓦葺の寄棟屋根を架ける。北棟の棟は西棟の棟より高く，西棟の棟を越えて西面に千鳥破風をつくり，浴室上部の湯気抜きとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000862"},{"id":"00000848","register_sub_id":"101","register_pk":"101838","name":"近江神宮宿衛舎","kana":"おうみじんぐうしゅくえいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03205214,"lng":135.85225488,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0070","desc":"楼門・神符授与所・外廻廊とともに外院を形成する。楼門の南袖塀に取付く東西棟，切妻屋根の建物で，神符授与所と同様に外廻廊の一間分を閉鎖して玄関とする。構造・規模・形式も神符授与所と同じで，両妻側に小庇をつけて立面を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000848"},{"id":"00000839","register_sub_id":"101","register_pk":"101829","name":"近江神宮神庫","kana":"おうみじんぐうじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積８㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0061","desc":"本殿の左手後方，内内院の南西隅に位置する南北棟の切妻造，檜皮葺，平入の揚床式倉庫で，柱は面取角柱とし，組物は舟肘木を用いる。横板を落込んで壁をつくり，妻飾は豕叉首として，破風に懸魚を付ける。本殿の背後を整える重要な構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000839"},{"id":"00000856","register_sub_id":"101","register_pk":"101846","name":"近江神宮神饌所","kana":"おうみじんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03281911,"lng":135.85212315,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積53㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0078","desc":"第一期工事分の施設で，内院と同レベルの段の北方に位置し，第二期工事で神楽殿と結ばれる。南北棟の入母屋造建物で，南北両面に玄関口を設け，腰を竪羽目，腰長押以上を横板落込みとし，西北に簓子下見の付属屋を張りだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000856"},{"id":"00000857","register_sub_id":"101","register_pk":"101847","name":"近江神宮神饌所登廊","kana":"おうみじんぐうしんせんしょのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03279569,"lng":135.8521817,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積９㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0079","desc":"神楽殿の裏通路中央から階段で昇り，神饌所の当初からの東口である舞良戸に繋げる。外部竪羽目の簡素な登廊で，両接続部は切妻屋根とし，階段部は天井を棹縁天井として片流れの屋根を架けて外観に変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000857"},{"id":"00000847","register_sub_id":"101","register_pk":"101837","name":"近江神宮神符授与所","kana":"おうみじんぐうしんぷじゅよじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03225998,"lng":135.852331,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0069","desc":"第二期工事分に属し，内院の下の敷地東端に位置し，楼門・宿衛舎・外廻廊とともにいわゆる外院を形成する。楼門の北袖塀に取付く東西棟，切妻屋根の建物で，柱は角柱と丸柱を使い分ける。舟肘木を用い，妻飾は豕叉首とし，懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000847"},{"id":"00000841","register_sub_id":"101","register_pk":"101831","name":"近江神宮透塀（南部）","kana":"おうみじんぐうすきべい（なんぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造，檜皮葺，長さ36m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0063","desc":"翼廊南端に発し，内内院の南面を限り，西面で神庫の背面に接続する。構造･規模･形式は北部のものと同様とする。手前より三間目を連子の引戸とするのも同様。控えの斜材は鉄筋コンクリート製で，当初からのものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000841"},{"id":"00000840","register_sub_id":"101","register_pk":"101830","name":"近江神宮透塀（北部）","kana":"おうみじんぐうすきべい（ほくぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造，檜皮葺，長さ36m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0062","desc":"翼廊北端から発し，内内院の北面と西面を限り後門に連なる。土台建ちの面取角柱に秤肘木をのせ，檜皮葺の小屋根を置く。柱間は腰を１枚板，腰長押と内法長押の間を連子窓とする。五間目以西の棟を一段高め，内内院敷地の高低差に応じた造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000840"},{"id":"00000850","register_sub_id":"101","register_pk":"101840","name":"近江神宮外廻廊（南部）","kana":"おうみじんぐうそとかいろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03198774,"lng":135.85224903,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積15㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0072","desc":"外院の南翼廊にあたるところで，宿衛舎に取付く。当初は北翼廊と同様七間＋三間の規模を有した。北翼廊と同仕様であるが，東面は高床風とせずに，土間床上に高欄をつける。三間分を残すのみではあるが，外院を構成するうえで欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000850"},{"id":"00000849","register_sub_id":"101","register_pk":"101839","name":"近江神宮外廻廊（北部）","kana":"おうみじんぐうそとかいろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03232439,"lng":135.85239832,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積60㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0071","desc":"外院の翼廊にあたるところで，神符授与所に取付き，北端で西に矩折れて外透塀に接続する。切妻屋根，吹放ちの単廊で，外側に高床風の縁をせりだし高欄をまわす。柱は丸柱で，舟肘木を用い，妻飾を豕叉首として簡素な懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000849"},{"id":"00000851","register_sub_id":"101","register_pk":"101841","name":"近江神宮外透塀（南部）","kana":"おうみじんぐうそとすきべい（なんぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03237708,"lng":135.85126836,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造，銅板葺，建築面積10㎡","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0073","desc":"外院北翼廊の端部に発し，北神門に取付く五間分の屋根塀で，神楽殿・神楽殿廻廊に連なる外院北部（北神門地）の東面を限る。土台立ちの角柱に秤肘木を載せて小屋根を支える。柱間は腰長押と内法長押の間に連子窓を入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000851"},{"id":"00000853","register_sub_id":"101","register_pk":"101843","name":"近江神宮外透塀（北部）","kana":"おうみじんぐうそとすきべい（ほくぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03248832,"lng":135.85130642,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造，銅板葺，延長8m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0075","desc":"北神門に取付き，神楽殿廻廊に向かう四間分の屋根塀で，南外透塀とともに外院北部の東面を限る。仕様は南外透塀と同様とする。第二期工事分の箇所で，楼門・外廻廊等とともに朱塗と白壁に仕上げられ第一期工事による素木造の社殿群と対照をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000853"},{"id":"00000846","register_sub_id":"101","register_pk":"101836","name":"近江神宮外拝殿","kana":"おうみじんぐうそとはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03226291,"lng":135.85191238,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積157㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0068","desc":"内院敷地の東端に位置する桁行五間梁間三間，入母屋造の建物で，東面に高欄付の縁をせりだして懸造り風につくり，中央間に外院からの登石階段を割込ませる。正面石階段の上と背面中央とに唐破風をつけて割拝殿風にしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000846"},{"id":"00000869","register_sub_id":"101","register_pk":"101859","name":"近江神宮第一鳥居","kana":"おうみじんぐうだいいちとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03134665,"lng":135.855797,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造鳥居，幅7.3m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0091","desc":"表参道の入口に位置する鳥居で，第二期工事において建立される。反りのある棟木と島木，内転びの丸柱に角断面の貫と額束を入れた典型的な明神鳥居の形式をとる。幅約７ｍ。社域を明示するとともに，近江神宮のランドマークにもなっている鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000869"},{"id":"00000870","register_sub_id":"101","register_pk":"101860","name":"近江神宮第二鳥居","kana":"おうみじんぐうだいにとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03164524,"lng":135.85266472,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造鳥居，幅6.4m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0092","desc":"第一期工事分に係わる鳥居で，表参道の突き当たりの石階段を昇りきった地点に建つ。第一鳥居と同形式の明神鳥居で，幅約６ｍとやや小振りのものとする。参拝者は，この鳥居をくぐり右に折れて，手水舎の先左手の石階段を昇り楼門に向かうことになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000870"},{"id":"00000835","register_sub_id":"101","register_pk":"101825","name":"近江神宮中門","kana":"おうみじんぐうちゅうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03240928,"lng":135.85138546,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積７㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0057","desc":"登廊を昇りきったところに位置し，板唐戸をもって内内院の入口とする。切妻造，檜皮葺，桁行一間梁間一間の規模で，渡廊とは棟続きであるが，板唐戸の上部は，渡廊側を蟇股・斗・舟肘木とし，登廊側を豕叉首として体裁を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000835"},{"id":"00000868","register_sub_id":"101","register_pk":"101858","name":"近江神宮手水舎","kana":"おうみじんぐうちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03194968,"lng":135.85263251,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積18㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0090","desc":"第二鳥居の右手奥，楼門へ向かう石階段の左手脇に位置する。第一期工事分に属する施設で，内転びの隅柱に２本宛の控柱を添わせ，組物は舟肘木を用い，一軒疎垂木，銅板葺（当初は檜皮葺）の切妻屋根を架ける。妻飾は豕叉首とし，破風に懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000868"},{"id":"00000863","register_sub_id":"101","register_pk":"101853","name":"近江神宮勅使玄関","kana":"おうみじんぐうちょくしげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03324943,"lng":135.8528345,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0085","desc":"社務所東棟と斎館（貴賓館）との間に設けられた勅使のための玄関で，東面中央に軽快な唐破風をつける。舟肘木を用いた品格ある構えを見せ，内部は一間幅を中央で土間と廊下とに振分け，玄関の突当たりに棚を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000863"},{"id":"00000845","register_sub_id":"101","register_pk":"101835","name":"近江神宮内院廻廊（南部）","kana":"おうみじんぐうないいんかいろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03214289,"lng":135.85168697,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積129㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0067","desc":"内院は，内拝殿と一文字状の翼廊（各四間），外拝殿と同状の翼廊（各四間），内拝殿翼廊と外拝殿翼廊とを結ぶ北面の廊（八間）と南面の廊（八間）とにより囲われる。構造・規模・形式等は北廻廊と同様とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000845"},{"id":"00000844","register_sub_id":"101","register_pk":"101834","name":"近江神宮内院廻廊（北部）","kana":"おうみじんぐうないいんかいろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03247661,"lng":135.851807,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積129㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0066","desc":"内拝殿から北へ降り，更に北面で石階段を降り，外拝殿から北に伸びた翼廊に接続して内院を囲う。外側を連子窓，内側を開放とする単廊で，丸柱に舟肘木を用い，小屋組は豕叉首，軒は一軒とする。内院全体が当初は檜皮葺（現在は銅板葺）であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000844"},{"id":"00000843","register_sub_id":"101","register_pk":"101833","name":"近江神宮内拝殿","kana":"おうみじんぐうないはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積100㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0065","desc":"内院の西端，石階段付基壇上に建つ桁行五間梁間三間，入母屋造の建物で，背面に床を更に高くした三間×一間の張り出し部を設けて登廊に接続させる。天井は折上小組格天井。一旦内院内に展開した参拝動線を登廊越しの本殿へ向けて絞り込む役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000843"},{"id":"00000842","register_sub_id":"101","register_pk":"101832","name":"近江神宮登廊","kana":"おうみじんぐうのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積33㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0064","desc":"切妻造，銅板葺（当初は檜皮葺），桁行三間の単廊で，柱は丸柱，舟肘木を用い，豕叉首と斗で化粧棟木を支える。柱間は腰を板壁，腰長押と内法長押の間を硝子障子とする。社殿構成上の見せ所になり，棟は曲線を描いて内内院と内院をダイナミックに繋ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000842"},{"id":"00000833","register_sub_id":"101","register_pk":"101823","name":"近江神宮祝詞舎","kana":"おうみじんぐうのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積13㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0055","desc":"いわゆる「近江造」の特徴を示すところで，形態上は本殿の前面に張りだした切妻の向拝部を祝詞舎とするが，平面上は本殿前面の凸形状の浜縁部を祝詞舎に充てる。桁行一間梁間一間の規模で，全面吹放ちとし，三方に高欄付の縁を回す。天井は小組格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000833"},{"id":"00000832","register_sub_id":"101","register_pk":"101822","name":"近江神宮本殿","kana":"おうみじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積53㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0054","desc":"皇紀２６００年に合わせて新営された神社建築で，内務省神社局による集大成作品。設計は角南隆と谷重雄。傾斜地に対応した社殿の配置構成に特色がある。本殿は，三間社流造，檜皮葺で，棟に千木と堅魚木をあげて聖域地を明示させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000832"},{"id":"00000837","register_sub_id":"101","register_pk":"101827","name":"近江神宮翼廊（南部）","kana":"おうみじんぐうよくろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積22㎡，神饌弁備所を含む","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0059","desc":"中門に取付く一文字状の翼廊の南部分で，構造・規模・形式は翼廊北部分と同様とするが，桁行四間のうち南端の二間分を板唐戸（北面と南面）と連子窓（東面と西面）とにより囲って弁備所（仮神饌所）に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000837"},{"id":"00000836","register_sub_id":"101","register_pk":"101826","name":"近江神宮翼廊（北部）","kana":"おうみじんぐうよくろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03245612,"lng":135.85136204,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0058","desc":"中門に取り付き，内内院の東面を限る。渡廊に直交する一文字状の翼廊の北部分で桁行は四間。切妻屋根，檜皮葺で，外側を連子窓，内側を開放とする。柱は丸柱で，舟肘木を用い，小屋組は豕叉首，軒は一軒とし，化粧垂木には反りを付けずに簡明な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000836"},{"id":"00000871","register_sub_id":"101","register_pk":"101861","name":"近江神宮脇鳥居","kana":"おうみじんぐうわきとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03353046,"lng":135.85368051,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造鳥居，幅5.4m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0093","desc":"第一期工事の掉尾を飾る施設で，昭和１５年１２月３０日に竣工奉告祭を執行している。斎館（貴賓館）に通じる脇参道の入口に位置する。第一鳥居・第二鳥居と同型式の明神鳥居で，幅約５．４ｍと三つの鳥居のなかでは最も小振りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000871"},{"id":"00000834","register_sub_id":"101","register_pk":"101824","name":"近江神宮渡廊","kana":"おうみじんぐうわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0056","desc":"内内院の入口にあたる中門から祝詞舎に向けて伸びた梁間一間桁行三間の吹放ち廊下。柱は丸柱，舟肘木を用い，化粧棟木を虹梁・蟇股・斗で支える。屋根は切妻造，檜皮葺で，妻先を本殿向拝の下に重ね，本殿から登廊へ連なる屋根面のリズムを造りだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000834"},{"id":"00002777","register_sub_id":"101","register_pk":"103767","name":"大鳥神社神楽殿","kana":"おおとりじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.9124984,"lng":136.22236794,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0195","desc":"拝殿東方に建つ。方１間，入母屋造，妻入で，正側面３方に刎高欄付木口縁を巡らす。面取角柱上に舟肘木を置く簡素な施設だが，建具は３方舞良戸建て，内部背面は鏡板張りで老松を描き，神楽殿の構えを完備する。小規模ながら社殿構成上欠かせない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002777"},{"id":"00002781","register_sub_id":"101","register_pk":"103771","name":"大鳥神社社務所","kana":"おおとりじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.912453,"lng":136.221832,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積177㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0199","desc":"社殿の南西に東面して建つ。入母屋造，桟瓦葺で，正面中央に向唐破風造の式台を付ける。内部は２列６室に分け，南端に土間を設ける。内法・天井長押を廻し，主座敷には床・棚・付書院を備え，端正な彫刻欄間を入れるなど，簡明洗練された意匠にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002781"},{"id":"00002778","register_sub_id":"101","register_pk":"103768","name":"大鳥神社神饌所","kana":"おおとりじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91243958,"lng":136.22206484,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0196","desc":"拝殿西方，神楽殿に相対する位置に建つ。入母屋造，平入，北端１間通りを踏込土間とし出入口を開き，これより南の床上部の西・南面開口部の外に刎高欄付木口縁を矩折れに廻す。小規模ながら軸部は面取角柱，舟肘木で，開口部は半蔀を吊る本格的な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002778"},{"id":"00002775","register_sub_id":"101","register_pk":"103765","name":"大鳥神社祝詞殿（中門）","kana":"おおとりじんじゃのりとでん（ちゅうもん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91255292,"lng":136.2221946,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、檜皮葺、建築面積12㎡、左右透塀延長66m付","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0193","desc":"鎌倉時代以来佐々木氏の尊崇を得た神社。貞享２年建立の本殿が残るが，他は大正４年火災後の再建になる。祝詞殿は本殿前に建つ桁行２間，梁間１間，前後唐破風造の建物で，左右矩折れに透塀を付属する。巧みな構成と優美な意匠で社殿中核の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002775"},{"id":"00002776","register_sub_id":"101","register_pk":"103766","name":"大鳥神社拝殿","kana":"おおとりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.912678,"lng":136.222168,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0194","desc":"祝詞殿前方に独立して建つ。方３間，入母屋造，妻入で，４周に刎高欄付木口縁を巡らす。柱間は吹放しで，正背面中央間の内法を一段高くし，内部は二重折上小組格天井とする。細い木割と深い軒の出による優美な外観は社殿の中心にあって最も目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002776"},{"id":"00002779","register_sub_id":"101","register_pk":"103769","name":"大鳥神社神輿蔵","kana":"おおとりじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91252346,"lng":136.2219903,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0197","desc":"神饌所の北に建つ。土蔵造，寄棟造，本瓦葺で，正面に桟瓦葺の庇を付け，２箇所の戸口を開く。内部は壁・床とも板張りで竿縁天井を張り，御輿，祭器を収める。丁寧な仕事になる堅牢な造りであるとともに，出の大きな軒蛇腹，換気用の丸い小窓など特徴を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002779"},{"id":"00002780","register_sub_id":"101","register_pk":"103770","name":"大鳥神社楼門","kana":"おおとりじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91225024,"lng":136.22226284,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造楼門、檜皮葺、建築面積27㎡、左右透塀延長77m付","structure_material":"木造楼門","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0198","desc":"三間一戸，切妻造の楼門で，左右折れ廻りに透塀を廻し境内を区切る。腰組は三手先，上層は出三斗とし，中備は蟇股，間斗束，妻は二重虹梁蟇股である。柱の隅延び，垂木・桁の反増し等中世の技法を忠実に踏襲した優美な意匠となる。設計は京都府技師亀岡末吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002780"},{"id":"00003252","register_sub_id":"101","register_pk":"104242","name":"乎加神社玉垣","kana":"おかじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17721025,"lng":136.18434858,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、銅板葺、延長52m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0212","desc":"幣殿の両脇から左右に若干延びて，本殿，祝詞殿を囲む。延長５２ｍで，石垣を築いた上に木造で塀を廻らし，屋根は銅板葺とする。内側には控柱を設け，各柱間には菱格子を嵌めている。本殿等同時期の建設と伝えられ，本殿廻りの内外を画す建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003252"},{"id":"00003254","register_sub_id":"101","register_pk":"104244","name":"乎加神社手水舎","kana":"おかじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17673093,"lng":136.18454841,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積7.7㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0214","desc":"境内の入り口付近に位置する桁行２間梁間１間規模，入母屋造の手水舎。柱はやや内転びとし，木鼻付虹梁形頭貫，蟇股，菱格子欄間など各種の装飾を備える。小規模ではあるが本格的な形式を備え，近代社殿建築の特徴を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003254"},{"id":"00003251","register_sub_id":"101","register_pk":"104241","name":"乎加神社祝詞殿","kana":"おかじんじゃのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.177044,"lng":136.18431072,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0211","desc":"本殿と幣殿とを繋ぐ桁行２間梁間１間，切妻造の社殿。幣殿に合わせて床を高く張り，内法長押上の小壁には菱格子欄間を入れ開放的なつくりとする。本殿と同時期の建設と伝えられ，社殿構成上欠くことのできない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003251"},{"id":"00003253","register_sub_id":"101","register_pk":"104243","name":"乎加神社拝殿","kana":"おかじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.176846,"lng":136.18425814,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0213","desc":"幣殿の正面に建つ桁行３間梁間３間の社殿。この地域によく見られる床を設けない構成で，天井は折り上げ格天井とする。屋根は檜皮葺に銅板を被せる入母屋造で，軒は二軒とする。豪壮な土間建ちの拝殿であり，社殿景観上欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003253"},{"id":"00003250","register_sub_id":"101","register_pk":"104240","name":"乎加神社幣殿","kana":"おかじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17699562,"lng":136.18430104,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0210","desc":"本殿・祝詞殿の前面に位置する桁行７間梁間２間，入母屋造の社殿で，正面に唐破風屋根の拝所を設ける。中央３間は一段高い切妻屋根とし，両脇は入母屋造とする。建ちの高い本殿と対置される建築で，荘厳な外観が特徴の近代神社建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003250"},{"id":"00003249","register_sub_id":"101","register_pk":"104239","name":"乎加神社本殿","kana":"おかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17711783,"lng":136.18432545,"geo_status":"db","era":"明治初期／明治25移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0209","desc":"桁行３間，梁間２間，独立棟持柱を有する神明造の社殿。屋根は檜皮葺とし，棟に千木と堅魚木７本を載せる。四周に縁を廻らし，正面以外は板壁とする。明治２２年の伊勢神宮遷宮に際し別宮を譲り受け，２５年に当地に移築したものと伝えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003249"},{"id":"00001621","register_sub_id":"101","register_pk":"102611","name":"海門山満月寺浮御堂","kana":"かいもんさんまんげつじうきみどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.109852,"lng":135.92157,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡、長さ17m・幅員2.6m石橋附属","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0126","desc":"琵琶湖上に建つ三間仏堂で，湖畔から延びる長さ約１７ｍの石橋が附属する。平安中期に湖上安全と衆生救済を願って千体の阿弥陀仏を奉る堂を建てたのを始まりと伝える。近江八景のひとつ「堅田の落雁」で知られる景勝地の重要な構成要素。設計は西崎辰之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001621"},{"id":"00001622","register_sub_id":"101","register_pk":"102612","name":"海門山満月寺観音堂","kana":"かいもんさんまんげつじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.11002793,"lng":135.9212681,"geo_status":"db","era":"明和3","year":1766,"year_source":"db","year_min":1766,"year_max":1766,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0127","desc":"琵琶湖畔に営まれた臨済宗寺院満月寺の本堂。入母屋造の三間堂で内部は瓦の四半敷とし，本尊木造聖観音座像（重要文化財）を安置する。近年の修理で正面の柱間装置を変更し，向拝を増設するなどの変更はあるが，湖上の浮御堂とともに一体の寺観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001622"},{"id":"00001623","register_sub_id":"101","register_pk":"102613","name":"海門山満月寺客殿","kana":"かいもんさんまんげつじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.10989945,"lng":135.92101624,"geo_status":"db","era":"宝暦4","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0128","desc":"琵琶湖に向かって東面して建ち，北側面に式台付大玄関を構える。屋根は入母屋造で，もとこけら葺。内部は，前列に八畳と十畳の客間，後列に内玄関と仏間を配し，正面及び南側面に広縁を廻す。四間取り形式の客殿の姿を良く伝える。地元大工吉兵衛の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001623"},{"id":"00001624","register_sub_id":"101","register_pk":"102614","name":"海門山満月寺山門","kana":"かいもんさんまんげつじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.11006669,"lng":135.92105172,"geo_status":"db","era":"文化9","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造楼門、瓦葺、建築面積3㎡","structure_material":"木造楼門","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0129","desc":"境内西北部の入口に西面して建つ楼門で，初層軸部の周囲に漆喰塗りの袴腰を付けたいわゆる竜宮造の形式になる。上層は桁行二間，梁間一間で四周各間に菱格子窓を構える。高欄や腰組などの細部に特色がある。扉はなく，東方正面に浮御堂を見通すことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001624"},{"id":"00001625","register_sub_id":"101","register_pk":"102615","name":"海門山満月寺茶室（玉鈎亭）","kana":"かいもんさんまんげつじちゃしつ（ぎょくこうてい）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.10970048,"lng":135.92096231,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0130","desc":"昭和９年の台風で倒壊した前身浮御堂の古材を天井などの一部に用いて建築，昭和６３年に客殿南から現在地に移築された。七畳下座床の席と四畳向切枡床の席が水屋を介して繋がっていたが，移築に伴い水屋を撤去，現在は２席が東西に接し，棟をＬ型に連ねる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001625"},{"id":"00012174","register_sub_id":"101","register_pk":"352974","name":"瓦屋寺開山堂","kana":"かわらやじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124312,"lng":136.183708,"geo_status":"db","era":"元禄13年(1700)／昭和前期改修","year":1700,"year_source":"db","year_min":1700,"year_max":1700,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-412","desc":"本堂の南西方の高台に建つ。開山堂、相の間、礼堂からなる。開山堂は方二間、宝形造、瓦葺で、土台上に粽付円柱を立て、台輪を廻し出三斗を組む。側面前方に花頭窓を穿ち、禅宗様の意匠をみせる。禅宗寺院の開山堂の形式をよく残しており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012174"},{"id":"00012175","register_sub_id":"101","register_pk":"352975","name":"瓦屋寺経堂（海印蔵）","kana":"かわらやじきょうどう（かいいんぞう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124234,"lng":136.183882,"geo_status":"db","era":"享保10年（1725)","year":1725,"year_source":"db","year_min":1725,"year_max":1725,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡、輪蔵付","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-413","desc":"本堂の南方に北面して建つ。方三間、宝形造、桟瓦葺。角柱で組物は平三斗、各面中央間に桟唐戸をたてこみ、正面両端間のみ花頭窓を穿つ。内部中央に八角輪蔵を置く。四隅の火打梁上に太瓶束を立て四方に桁を廻し、側柱と海老虹梁で繋ぐ架構に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012175"},{"id":"00012178","register_sub_id":"101","register_pk":"352978","name":"瓦屋寺庫裏","kana":"かわらやじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124859,"lng":136.183889,"geo_status":"db","era":"明治4年","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積379㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-416","desc":"本堂後方に南面する。正面は、中央に向唐破風造の式台玄関を付け、東側に出入口二所を開き腰海鼠壁を施す。内部は前後二列に七室を配し、奥座敷は床の間、床脇、付書院を設け良質な意匠をもつ。土間上部に壮大な梁組をみせ、式台玄関の細部意匠も秀逸な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012178"},{"id":"00012173","register_sub_id":"101","register_pk":"352973","name":"瓦屋寺地蔵堂","kana":"かわらやじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124623,"lng":136.183506,"geo_status":"db","era":"正保年間(1644-1647)／昭和前期改修","year":1646,"year_source":"estimated","year_min":1644,"year_max":1647,"year_label":"正保年間(1644-1647)","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-411","desc":"本堂西に渡廊下で接続する。桁行三間、梁間四間、切妻造、桟瓦葺。組物は舟肘木で、内部や小屋組は改変されているが、堂内後方仏壇の前面柱はもと来迎柱で、上部に三斗を組む。柱は角柱で、木太く、正面の桟唐戸もよく残る。本堂とともに伽藍を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012173"},{"id":"00012177","register_sub_id":"101","register_pk":"352977","name":"瓦屋寺鐘楼","kana":"かわらやじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124572,"lng":136.183837,"geo_status":"db","era":"正保年間(1644-1647)","year":1646,"year_source":"estimated","year_min":1644,"year_max":1647,"year_label":"正保年間(1644-1647)","structure":"木造、瓦葺、面積9.2㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"25-415","desc":"本堂前方で賓頭盧堂の北に建つ。方一間、切妻造、桟瓦葺で、礎盤上に一六面取角柱を四方転びに立て、腰貫、飛貫、頭貫で固める。組物は造らず、化粧棟木を受ける実肘木の絵様にわずかに装飾をみせる。木柄が太く堂々たる構えで、境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012177"},{"id":"00012176","register_sub_id":"101","register_pk":"352976","name":"瓦屋寺賓頭盧堂","kana":"かわらやじびんずるどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124489,"lng":136.183853,"geo_status":"db","era":"文政元年(1818)","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-414","desc":"本堂前方に西面して建つ。方一間、宝形造、桟瓦葺。角柱で台輪を廻し、組物は出組の詰組で、軒は扇垂木とする。正面に桟唐戸をたてこみ、内部は土間で賓頭盧像を安置し、棹縁天井を張る。小規模ながら、細部まで禅宗様の意匠でまとめられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012176"},{"id":"00012172","register_sub_id":"101","register_pk":"352972","name":"瓦屋寺本堂","kana":"かわらやじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124648,"lng":136.183705,"geo_status":"db","era":"正保2年(1645)","year":1645,"year_source":"db","year_min":1645,"year_max":1645,"year_label":null,"structure":"木造平屋建、茅葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-410","desc":"箕作山の境内に南面する。桁行三間、梁間四間、入母屋造、茅葺で向拝一間。堂内は一室で中央後寄りに須弥壇、背面両端に脇壇を設ける。円柱に台輪を載せ組物は出三斗で、正面中備は頭貫下に蟇股、上に間斗束を重ねる。和様と禅宗様を巧みに取り入れた本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012172"},{"id":"00014041","register_sub_id":"101","register_pk":"508301","name":"観音正寺護摩堂","kana":"かんのんしょうじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14505278,"lng":136.16067222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0491","desc":"繖山に所在する古刹の仏堂。地蔵堂南に西面して建つ。三間四方、正面入母屋造背面切妻造桟瓦葺で向拝が付く。内部は一室で棹縁天井とし、奥一間に仏壇を設ける。安永建立の元三大師堂の部材を再用して建立した近代の仏堂で、境内の変遷を知る上でも貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014041"},{"id":"00014040","register_sub_id":"101","register_pk":"508300","name":"観音正寺地蔵堂","kana":"かんのんしょうじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14510556,"lng":136.16059167,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0490","desc":"繖山に所在する古刹の小堂。本堂南に西面して建つ。二間四方宝形造桟瓦葺。丸柱で平三斗を置き、軒は一軒繁垂木。正面に切目縁と庇を設け、中央間を半蔀、両脇を花頭窓とする。内部は一室で奥半間を仏壇とし、虹梁を架ける。巡礼寺院の様相を伝える仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014040"},{"id":"00014039","register_sub_id":"101","register_pk":"508299","name":"観音正寺書院","kana":"かんのんしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14459167,"lng":136.16116111,"geo_status":"db","era":"寛政8年(1796)","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0489","desc":"繖山に所在する古刹の書院。境内中央南寄りに西面する。入母屋造桟瓦葺で正面北寄りに唐破風玄関を構える。平面は六室とし、南に土間、北と東に入側縁を配す。上段の間は折上小組格天井とする書院座敷。江戸後期の姿をよく留め、山岳大寺院の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014039"},{"id":"00014045","register_sub_id":"101","register_pk":"508305","name":"観音正寺書院庭門","kana":"かんのんしょうじしょいんにわもん","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14478611,"lng":136.16081111,"geo_status":"db","era":"天保15年（1844)","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0495","desc":"書院北側の庭園を矩折に囲む土塀の西面に開く。一間一戸薬医門で、切妻造桟瓦葺、軒は一軒疎垂木とする。本柱、控柱とも角柱で、間口に両開きの板戸を吊る。五平の本柱を冠木上まで貫通させて栓でとめるのは珍しい。書院と一体で残る近世遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014045"},{"id":"00014043","register_sub_id":"101","register_pk":"508303","name":"観音正寺鐘堂","kana":"かんのんしょうじしょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14443333,"lng":136.16126667,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0493","desc":"繖山に所在する古刹の鐘堂。境内南端に位置する。切妻造本瓦葺、方一間八角柱内転びの鐘楼で、各間二本の角柱の間柱を立て、本柱と間柱を腰貫と二本の飛貫で連結する。両妻虹梁上に大瓶束をのせ、内側に虹梁を架け渡し鐘を吊る。延暦寺鐘楼と共通する構造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014043"},{"id":"00014044","register_sub_id":"101","register_pk":"508304","name":"観音正寺手水舎","kana":"かんのんしょうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14485278,"lng":136.16075833,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、面積1.5㎡","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0494","desc":"繖山に所在する札所寺院の手水舎。書院庭門の北に建つ南北棟で西面する。切妻造銅板葺、石製控柱を添えた本柱二本を虹梁で繋ぎ、控柱を添えた肘木で腕木を支え、腕木は桁を受ける。本柱上に平三斗、虹梁中央に蟇股を置く。巡礼寺院の歴史的景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014044"},{"id":"00014042","register_sub_id":"101","register_pk":"508302","name":"観音正寺札堂","kana":"かんのんしょうじふだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14496667,"lng":136.16072222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0492","desc":"札所寺院の小堂。護摩堂南に西面して建つ。桁行三間、梁間二間、切妻造桟瓦葺平入、組物は大斗絵様肘木。正面は各間に虹梁形差物を入れ、半蔀を吊る。内部は一室で奥半間を仏壇とし虹梁を架ける。もとは三十三観音を祀り、巡礼寺院における特徴的な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014042"},{"id":"00003433","register_sub_id":"101","register_pk":"104423","name":"玉宝院本堂","kana":"ぎょくほういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市北清水町296","lat":35.143585,"lng":136.21698,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0223","desc":"集落のほぼ中央に位置する浄土宗本堂。桁行３間，梁間５間，入母屋造，正面向拝１間で，梁行きを前後に分け前方２間を外陣とし，後方は中央の内陣と左右脇陣を取る。組物や蟇股など細部意匠に優れ，後陣の下屋屋根を唐破風状にするなど，特異な納まりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003433"},{"id":"00013746","register_sub_id":"101","register_pk":"505299","name":"弘誓寺表門","kana":"ぐぜいじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13393611,"lng":136.19948333,"geo_status":"db","era":"享保6年(1721)","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 477","desc":"境内の南辺中央に位置し南面する四脚門。切妻造本瓦葺で両開き板戸を建てる。本柱は円柱で棟木下まで伸ばし、角柱の控柱の間に海老虹梁を架けて固め、桁行は楣を渡して中央に龍彫を嵌めた蟇股を載せる。急勾配でたちの高い屋根が参道起点の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013746"},{"id":"00006408","register_sub_id":"101","register_pk":"107391","name":"弘誓寺経蔵","kana":"ぐせいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190327,"lng":136.157227,"geo_status":"db","era":"天保6","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0250","desc":"鐘楼の西に隣接し、宝形造桟瓦葺で、正面に向拝１間を付ける。一軒疎垂木で軒を塗り込め、向拝には虹梁や木鼻に絵様を施し、中備は大きく猪目を開ける特異な形になる。堂内は１室で、床拭板張、棹縁天井で、三方に棚を付設する。軽快な佇まいの経蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006408"},{"id":"00013742","register_sub_id":"101","register_pk":"505291","name":"弘誓寺庫裏","kana":"ぐぜいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13438056,"lng":136.199575,"geo_status":"db","era":"文化2年(1805)","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積310㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 473","desc":"本堂西に玄関を介して接続する。切妻造桟瓦葺。南面し、切妻造の玄関を付す。妻飾は二重虹梁大瓶束笈形付で脇に海老虹梁を架け華美に飾る。平面は南半を台所、玄関、表の間、北半は二列六室として北西に床付座敷を配する。本堂とともに伽藍枢要の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013742"},{"id":"00006406","register_sub_id":"101","register_pk":"107389","name":"弘誓寺庫裏門","kana":"ぐせいじくりもん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190624,"lng":136.157516,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0253","desc":"庫裏の正面、太鼓堂の北側に連続して建つ。切妻造桟瓦葺で、太鼓堂側に潜戸と両開戸を立て、北側に部屋を設ける長屋門である。外壁は漆喰塗で、腰に竪板を張り、部屋正面には出格子窓を付ける。簡潔ながら、桁行８．８ｍに及ぶ規模を有し風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006406"},{"id":"00013743","register_sub_id":"101","register_pk":"505293","name":"弘誓寺玄関","kana":"ぐぜいじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13434444,"lng":136.199775,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺一部檜皮葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 474","desc":"庫裡・本堂間の中央に位置する。庫裏と本堂を結ぶ廊下の前方に式台、背後に四室を配する。屋根は切妻造桟瓦葺で、式台は唐破風造の檜皮葺。背後の四室は西に床付の座敷を配し、中央に二室、東に一室配する。式台の虹梁や破風廻りに彫刻を多用した大型の玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013743"},{"id":"00006407","register_sub_id":"101","register_pk":"107390","name":"弘誓寺鐘楼","kana":"ぐせいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.19029869,"lng":136.15728092,"geo_status":"db","era":"万治3","year":1660,"year_source":"db","year_min":1660,"year_max":1660,"year_label":null,"structure":"木造、瓦葺、面積8.5㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0249","desc":"境内の東南隅、通り近くに位置する。石積基壇上に建ち、桁行１間梁間１間で、四方を吹放す。南北棟の切妻造本瓦葺。柱は内転びの円柱で、柱上に大斗絵様肘木を置き、一軒疎垂木の化粧屋根裏とする。直截簡明な姿で、笈形など細部も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006407"},{"id":"00013745","register_sub_id":"101","register_pk":"505297","name":"弘誓寺鐘楼堂","kana":"ぐぜいじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.1338,"lng":136.19960833,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、建築面積13㎡","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 476","desc":"境内の東南に位置。高い石積基壇の上に四本の円柱を内転びに立て、腰貫、内法貫、頭貫で軸部を固める。組物は三斗で中備は蟇股である。妻は虹梁大瓶束として棟木を受ける。屋根は切妻造本瓦葺。境内では現存最古と考えられる。境内東南隅の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013745"},{"id":"00006405","register_sub_id":"101","register_pk":"107388","name":"弘誓寺太鼓堂","kana":"ぐせいじたいこどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190552,"lng":136.157471,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積28㎡、鼓楼付","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0252","desc":"茶所の北側に隣接して建つ。境内からは切妻造桟瓦葺に東西棟の入母屋造桟瓦葺の２階をのせるが、道路側からは２層櫓風の外観に見せる。２階は各面とも中央に柱を立てその両側に窓を穿ち、内部の中央に太鼓を吊る。真宗寺院らしい景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006405"},{"id":"00006749","register_sub_id":"101","register_pk":"107732","name":"弘誓寺茶所","kana":"ぐせいじちゃじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190468,"lng":136.15739938,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0251","desc":"本堂の前方、表大門の北に隣接して建つ。入母屋造桟瓦葺の２階建で、道路側に短い切妻屋根を出す。内部は南端に土間を設け、その北側西寄りに棹縁天井の広い板間とする。２階も畳敷などの部屋を間仕切り、小屋組をみせる。真宗寺院の茶所の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006749"},{"id":"00013744","register_sub_id":"101","register_pk":"505295","name":"弘誓寺中門","kana":"ぐぜいじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13424722,"lng":136.19962778,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 475","desc":"玄関への入口となる門。一間薬医門で柱間に両開きの腰舞良戸を建て屋根は桟瓦葺。背面に控柱を立て本柱と梁で繋ぎ、軒桁を受ける。垂木は疎らで反りが強い。板戸の橘の透彫や鬼瓦の井桁紋、瓦当の橘紋などに井伊家との関連を示す。小規模ながら格調ある門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013744"},{"id":"00006403","register_sub_id":"101","register_pk":"107386","name":"弘誓寺本堂","kana":"ぐせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.19067,"lng":136.157104,"geo_status":"db","era":"宝暦3","year":1753,"year_source":"db","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積657㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0248","desc":"境内の中央に東面して建つ。入母屋造本瓦葺で、正面に３間向拝を付け、桁行２２ｍ、梁間２０ｍに及ぶ。妻は二重虹梁大瓶束で、花頭窓を穿つ。内部は浄土真宗本堂の典型的な平面で、内陣は後門形式。近世中葉の近江地方における大規模で良質な真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006403"},{"id":"00011522","register_sub_id":"101","register_pk":"210472","name":"荒神山神社神楽殿","kana":"こうじんやまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23339694,"lng":136.19770194,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0396","desc":"境内の西南角に東面する。桁行三間、梁間三間、入母屋造、桟瓦葺。前方二間は舞台で正側面を半蔀とし、祭事には開放する。引違板戸を介し後方一間は楽屋で、背面中央間を出入口とする他は漆喰壁とする。保存状態も良く神社の祭事に欠かせない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011522"},{"id":"00011521","register_sub_id":"101","register_pk":"210471","name":"荒神山神社神饌所","kana":"こうじんやまじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23352889,"lng":136.19794389,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0395","desc":"拝殿の東縁に接続する。桁行二間、梁間二間、入母屋造、桟瓦葺。南面二間は中敷居を入れ、舞良戸を建て込む。内部は板敷の一室で、西北角に物入を作り、西面に板戸の出入口を設ける。妻飾は木連格子で、拝殿と一体となった社殿景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011521"},{"id":"00011523","register_sub_id":"101","register_pk":"210473","name":"荒神山神社鳥居","kana":"こうじんやまじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1872地先","lat":35.23389389,"lng":136.19755194,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、高さ9.0m、幅9.0m","structure_material":"石造","registered":"2017.05.02(平成29.05.02)","register_no":"25-0397","desc":"荒神山下の参道入口に立つ。柱間九・〇メートル、高さ九・〇メートルの大規模な石造明神鳥居。礎石上に直径約八六センチメートルの石柱を内転びで立て、貫と島木、笠木で固める。地元有志の発起の下、立てられたもので、神社の歴史を今に伝える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011523"},{"id":"00011519","register_sub_id":"101","register_pk":"210469","name":"荒神山神社拝殿","kana":"こうじんやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23352194,"lng":136.19788194,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0393","desc":"本殿の前面に渡殿を介して建つ。桁行三間、梁間三間、入母屋造、桟瓦葺。入母屋造妻入の向拝一間を付け正側面に縁を廻らす。組物は舟肘木で妻飾は木連格子とする。正背面中央間を両折桟唐戸とする以外は半蔀戸を吊る。優美な向拝が社殿景観を整える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011519"},{"id":"00011518","register_sub_id":"101","register_pk":"210468","name":"荒神山神社本殿","kana":"こうじんやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23361306,"lng":136.19782694,"geo_status":"db","era":"明治12年／昭和18年・平成8年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0392","desc":"荒神山山頂に南面して建つ。三間社流造、向拝一間付の社殿。前室付とし正面に両折桟唐戸を装置する。総檜造の上質な造りで、向拝の水引虹梁や蟇股に彫刻が見られるものの装飾が少なく、柱上は舟肘木、妻飾は豕扠首とするなど、復古的な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011518"},{"id":"00011520","register_sub_id":"101","register_pk":"210470","name":"荒神山神社渡殿","kana":"こうじんやまじんじゃわたりどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23356111,"lng":136.197845,"geo_status":"db","era":"明治28年／昭和18年・平成8年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0394","desc":"本殿と拝殿を繋ぐ南北棟の建物。桁行二間、梁間一間、切妻造銅板葺。両側面は腰長押、内法長押を内外に廻らし、格子窓を入れる。内部は拭板張で棹縁天井を張る。組物は舟肘木で拝殿と共通した意匠を見せ、社殿景観を構成する要素の一つとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011520"},{"id":"00003435","register_sub_id":"101","register_pk":"104425","name":"弘誓寺本堂","kana":"こうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市中一色町380","lat":35.14577424,"lng":136.2449888,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0225","desc":"桁行約１４ｍ，梁間約１５ｍ，入母屋造で，正面に３間分の広い向拝を付す。三方吹き放しの縁を回した外陣の先に一段高く矢来を取り，その奥中央に後門形式の内陣，両脇に余間を配す。縁先に軒支柱を立てた形式で，近世末浄土真宗大型本堂の姿をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003435"},{"id":"00004985","register_sub_id":"101","register_pk":"105975","name":"西願寺本堂","kana":"さいがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市船木町1246","lat":35.14040162,"lng":136.07637331,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0232","desc":"前半が外陣，後半が内陣と両脇陣からなる平面構成で，周囲に広縁等を廻し，正面に向拝を設ける。屋根は入母屋造，茅葺で，４周に桟瓦葺の下屋を廻し，向拝は一段切り上げる。外観民家風の浄土宗本堂で，年代は構造形式や細部から１７世紀中期頃と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004985"},{"id":"00002281","register_sub_id":"101","register_pk":"103271","name":"西教寺灌頂蔵","kana":"さいきょうじかんちょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08183466,"lng":135.86612138,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0157","desc":"浴室と内司課蔵との間に南面して建つ。切妻造・平入，桟瓦葺で，南面中央に観音開扉を設け，蔵前の庇をつける。軒廻りは一軒で垂木を塗籠め，外壁は腰を縦板張とする。内部は２階建で内司課蔵よりたちが高く，軒廻りの扱いにも造形の違いがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002281"},{"id":"00002274","register_sub_id":"101","register_pk":"103264","name":"西教寺観瀾亭","kana":"さいきょうじかんらんてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081406,"lng":135.865875,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0150","desc":"伽藍の西側，重文の客殿と新書院の間の背後に建つ。南側入母屋造・北側寄棟造で桟瓦葺，平屋建。内部は床の間・棚付の８畳間と棚のある６間畳の２室からなる。内外とも朱の砂壁で，面皮長押を用い，波をあしらった板欄間など，数寄屋風の瀟洒な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002274"},{"id":"00002272","register_sub_id":"101","register_pk":"103262","name":"西教寺客殿通用門","kana":"さいきょうじきゃくでんつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081062,"lng":135.867142,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、檜皮葺、間口2.1m","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0148","desc":"客殿の南面を区切る板塀の間に設けられた平唐門。面取角柱の親柱に腕木をつけて軒桁を受け，棟木は舟肘木で受ける。垂木は大疎とし，屋根は檜皮葺，妻に彫物懸魚をつける。簡素な意匠であるが，全体の比例が良好で，近代和風の建築技量があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002272"},{"id":"00002271","register_sub_id":"101","register_pk":"103261","name":"西教寺御廟","kana":"さいきょうじごびょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08107307,"lng":135.86552032,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0147","desc":"伽藍の南西，本堂の西の高台にある。四半敷の基壇に建ち，平面は桁行１間・梁間２間だが方形で，正面に向拝を設ける。屋根は宝形造で，軒は二軒繁垂木，組物が二手先で先端に絵様をつけた尾垂木を組む。蟇股や手挟など彫刻が豊かで，江戸末期の造形を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002271"},{"id":"00002285","register_sub_id":"101","register_pk":"103275","name":"西教寺宗祖大師殿","kana":"さいきょうじしゅうそだいしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080486,"lng":135.86673,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0161","desc":"明治１１年真盛宗別派独立に伴い，本堂南の一段低い地に建設された。入母屋造・桟瓦葺，正面軒唐破風付で，丸柱・舟肘木の軸部，疎垂木・木舞打の軒廻り，擬宝珠高欄付の縁など，格式の高い住宅建築の意匠になる。内部の小組格天井や筬欄間なども繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002285"},{"id":"00002286","register_sub_id":"101","register_pk":"103276","name":"西教寺宗祖大師殿唐門","kana":"さいきょうじしゅうそだいしでんからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080345,"lng":135.867004,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造四脚門、瓦葺、間口4.2m、左右袖塀全長3m及び築地塀全長38m付","structure_material":"木造四脚門","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0162","desc":"大師殿の正面，東面して建つ１間１戸の四脚門で，両側に折曲がりの築地塀が延びる。屋根は檜皮葺で，入母屋造・前後軒唐破風付。組物は三斗組と簡素だが，虹梁上に配された龍や獅子など多彩な彫刻，彫物欄間や板欄間，精緻な飾金具など，華やかな造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002286"},{"id":"00002287","register_sub_id":"101","register_pk":"103277","name":"西教寺宗祖大師殿通用門","kana":"さいきょうじしゅうそだいしでんつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080544,"lng":135.867004,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平唐門、瓦葺、間口3.0m、左右袖塀全長3m及び築地塀全長43m付","structure_material":"木造平唐門","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0163","desc":"大正期の伽藍整備の一環で建設された。大師殿の西側，基壇上に建つ１間１戸の平唐門で，両側に折曲がりの築地塀が延びる。屋根は檜皮葺で，軒は大疎垂木。通用門のため簡素なつくりであるが，規模が大きく，棟通りの大柄な蟇股が意匠の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002287"},{"id":"00002288","register_sub_id":"101","register_pk":"103278","name":"西教寺宗祖大師殿水屋","kana":"さいきょうじしゅうそだいしでんみずや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080601,"lng":135.867172,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、瓦葺、建築面積4.4㎡","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0164","desc":"唐門などともに大正期の伽藍整備で建設された。六角形平面で円形花型の水盤を覆い，桟瓦葺屋根で宝珠をのせる。長押で固めた６本柱で，六角に組んだ桁を支える。通用門と対面した位置に建ち，大師殿伽藍の北側の景観上，欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002288"},{"id":"00002273","register_sub_id":"101","register_pk":"103263","name":"西教寺書院","kana":"さいきょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081608,"lng":135.866089,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積490㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0149","desc":"大正６年の不断（常）念仏十五万大法会に際し客殿北側に対面して建てられた。桁行１３間，梁間９間，入母屋造，桟瓦葺で，内部は南側４室の表書院と北側６室の裏書院からなる。伝統的な書院造を踏襲しながら，全体に木太く，端正で力強い造形となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002273"},{"id":"00002275","register_sub_id":"101","register_pk":"103265","name":"西教寺新座敷","kana":"さいきょうじしんざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081207,"lng":135.865875,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0151","desc":"重文の客殿の背後，南西に建つ。東西棟で，東面切妻造・西面入母屋造，桟瓦葺，平屋建。内部は観瀾亭と同じく床の間・棚付の８畳間と棚のある６畳間の２室からなる。内外とも白漆喰壁だが，柱や長押にはベンガラを塗る。簡素で端正な数寄屋風の建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002275"},{"id":"00002282","register_sub_id":"101","register_pk":"103272","name":"西教寺正教蔵","kana":"さいきょうじせいきょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08125942,"lng":135.86677904,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0158","desc":"本堂の東側にある２階建の土蔵。切妻造・桟瓦葺で，西面には切妻造・起り屋根の庇を設け，蔵前とする。外壁は上部白漆喰塗，下部縦板張とし，蔵前は柱から軒裏まで漆喰で塗り込める。庇の虹梁絵様や誇張的な板蟇股などに，明治初期の意匠が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002282"},{"id":"00002277","register_sub_id":"101","register_pk":"103267","name":"西教寺内司課客殿","kana":"さいきょうじないしかきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081821,"lng":135.865891,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0153","desc":"書院の北東にある管長の執務室で，南に池を望む。南北棟で，屋根は寄棟造・桟瓦葺，軒を疎垂木・木舞打とし，側桁は舟肘木で受ける。内部は天井がやや高い床付の８畳間と６畳間からなるが，猿頬面取の竿縁天井など，細部には繊細な造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002277"},{"id":"00002280","register_sub_id":"101","register_pk":"103270","name":"西教寺内司課蔵","kana":"さいきょうじないしかくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081841,"lng":135.866028,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0156","desc":"内司課は管長のための空間になっている。蔵は書院の北側，内司課庫裏の東側に南面して建つ。切妻造・平入，桟瓦葺で，南面中央に観音開扉を設け，ここに蔵前の切妻造の庇をつける。庇は軒裏まで塗籠め，外壁は腰を縦板張とする。小規模だが，丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002280"},{"id":"00002278","register_sub_id":"101","register_pk":"103268","name":"西教寺内司課庫裏","kana":"さいきょうじないしかくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081829,"lng":135.865936,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0154","desc":"書院の北東にあり，管長の居住に用いられたもので，内司課客殿の東側に並立して建つ。南北棟の入母屋造・桟瓦葺で，妻は木連格子とする。南側に座敷を配し，北側に台所や風呂場を設ける。内向きのため規模は大きくないが，客殿と一連の造形を具備している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002278"},{"id":"00002279","register_sub_id":"101","register_pk":"103269","name":"西教寺内司課渡廊下","kana":"さいきょうじないしかわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.0817688,"lng":135.86586072,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0155","desc":"書院の北西隅から内司課客殿の南西隅に続く渡廊下。幅約３尺で，軸部は角柱・舟肘木で丸桁を受け，丸桁を虹梁で繋ぎ，虹梁上の蟇股・舟肘木で棟木をうける。軒は疎垂木・木舞打。蟇股や虹梁の形状が優美で，いずれの部材も面取するなど，丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002279"},{"id":"00002284","register_sub_id":"101","register_pk":"103274","name":"西教寺納骨堂","kana":"さいきょうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08094324,"lng":135.86663086,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0160","desc":"入母屋造・桟瓦葺の本屋を高くして，周囲に庇を廻す。軒は本屋・庇とも一軒疎垂木・木舞打で軽快につくる。内部は外陣・内陣の構成になり，内陣奥に通し仏壇を設ける。本堂の東南に建ち，棟を直交させ複雑で動きのある外観で，景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002284"},{"id":"00002283","register_sub_id":"101","register_pk":"103273","name":"西教寺水屋","kana":"さいきょうじみずや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08083396,"lng":135.86640359,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造、瓦葺、建築面積4.4㎡","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0159","desc":"本堂南に建つ。長方形平面で，中央に細長い水盤を置く。軸部は角柱を建てて，斜材で補強し，三斗を組んで桁を受け，天井は格天井とする。屋根は入母屋造・本瓦葺，二軒繁垂木で深い軒をつくり，小規模な建築であるが，堂々とした外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002283"},{"id":"00002276","register_sub_id":"101","register_pk":"103266","name":"西教寺浴室","kana":"さいきょうじよくしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08183142,"lng":135.86637496,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0152","desc":"書院の北東にあり，僧侶の浴室として使用されてきた。ＲＣ造，南北棟の切妻造・妻入で，屋根は銅板葺。平面は棟通りで左右にわかれ，前半が脱衣室，後半が浴槽になる。柱，長押，舟肘木さらに妻の破風や懸魚など，木造の形式をＲＣで忠実に再現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002276"},{"id":"00014046","register_sub_id":"101","register_pk":"508306","name":"沙沙貴神社旧源照殿（霜楓園）","kana":"ささきじんじゃきゅうげんしょうでん（そうふうえん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市安土町常楽寺字四ノ坪2","lat":35.13653611,"lng":136.135025,"geo_status":"db","era":"大正8年／昭和37年頃移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0496","desc":"東廻廊外側に位置する祭儀控え室の座敷棟。入母屋造桟瓦葺。北から八畳と六畳、南に三畳と四畳半を東西に並べ、北東に矩折れに縁を廻す。八畳は書院座敷で、四畳半は北に床と西に床脇、三畳は南に丸形の下地窓とし茶室の設えとする。格調高い近代の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014046"},{"id":"00002637","register_sub_id":"101","register_pk":"103627","name":"地蔵院本堂","kana":"じぞういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市大沢町345","lat":35.136665,"lng":136.251358,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0188","desc":"町内唯一の真言宗寺院の本堂。桁行梁間各３間，向拝１間，入母屋造，桟瓦葺で，方柱上に平三斗組物，中備に蟇股を載せ，１軒繁垂木の軒を受ける。内部は内外陣に仕切り，内陣奥には丸柱を立て凸型に仏壇を構える。江戸末期の小規模密教本堂の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002637"},{"id":"00002396","register_sub_id":"101","register_pk":"103386","name":"實成坊門","kana":"じっせいぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080627,"lng":135.867538,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0165","desc":"實成坊は近世より続く西教寺の塔頭のひとつである。敷地南の門は１間１戸の薬医門で，軒が疎垂木，屋根が桟瓦葺。組物は簡素な絵様肘木であるが，妻の虹梁・大瓶束架構を見所とする。両側に続く穴太衆積の石垣と一体となって参道景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002396"},{"id":"00003106","register_sub_id":"101","register_pk":"104096","name":"浄華寺本堂","kana":"じょうけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市下里町296","lat":35.13998272,"lng":136.25651183,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積131㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0202","desc":"仏堂と庫裏を兼ねた堂庫裏形式の浄土宗本堂。屋根は入母屋造，茅葺（現在鉄板仮覆）の四方に桟瓦葺の庇を付ける農家風の外観となる。間仕切や床，天井などに何回かの改造があるが，近世初期の小規模な道場建築のありさまをしのぶことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003106"},{"id":"00002638","register_sub_id":"101","register_pk":"103628","name":"昌善寺本堂","kana":"しょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市南菩提寺町680","lat":35.14188239,"lng":136.23157958,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0189","desc":"集落の南端にある浄土宗寺院の本堂。桁行５間，梁間７間，向拝１間，入母屋造，桟瓦葺で，前方外陣の奥，中央を内陣，その両脇を脇陣とし，内陣の奥に寄せて大型の須弥壇を構える。平面形式や内陣廻りの派手な彫刻・極彩色に明治期の新たな傾向が看取される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002638"},{"id":"00002641","register_sub_id":"101","register_pk":"103631","name":"白鬚神社社務所","kana":"しらひげじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市鵜川215","lat":35.27465362,"lng":136.01131954,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0192","desc":"比良山を神体山とする古社の社務所。田字型平面の座敷部の奥に貴賓室，前方に玄関・札所などを配する。入母屋造，妻入で唐破風造の式台を構え，一方に切妻屋根の突出部を付す正面の構えは中世の主殿を彷彿とさせ，古風な細部装飾と併せ巧みな意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002641"},{"id":"00002400","register_sub_id":"101","register_pk":"103390","name":"真盛園講堂（旧専門学寮講堂）","kana":"しんせいえんこうどう（きゅうせんもんがくりょうこうどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08114128,"lng":135.868408,"geo_status":"db","era":"昭和12／平成10移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0169","desc":"大正９年に開設された真盛派の僧侶学校である専門学寮の講堂として建てられた。ほぼ方形の平面で，寄棟造・桟瓦葺の屋根を架け，４周に擬宝珠高欄を廻す。疎垂木の軒や舟肘木，細やかな部材構成など，伝統的な住宅の形式を近代の造形感覚で具現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002400"},{"id":"00000695","register_sub_id":"101","register_pk":"101685","name":"新善光寺山門","kana":"しんぜんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市林256","lat":35.02881281,"lng":136.02319522,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造楼門，瓦葺，建築面積70㎡","structure_material":"木造楼門","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0043","desc":"本堂の正面に建つ大規模な三間三戸楼門で，門扉はなく側面の板壁のみの極めて開放的な造りになる。虹梁型の内法貫及び繋梁で上部を固める。軒廻りは尾垂木付，縁腰組は拳鼻付の三手先詰組とし，二軒繁垂木で深い軒を支えた重厚な造りとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000695"},{"id":"00000694","register_sub_id":"101","register_pk":"101684","name":"新善光寺本堂","kana":"しんぜんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市林256","lat":35.02928435,"lng":136.02366676,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積308㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0042","desc":"鎌倉時代の創建と伝え，本尊は善光寺阿弥陀如来の分身を祀る古刹で，本堂は善光寺に倣って内々陣，内陣，外陣を一体的に造る撞木造とし，地下には「胎内巡り」を設ける。外陣は正側面の入母屋屋根に軒唐破風を付加するなど賑やかに飾る大建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000694"},{"id":"00004139","register_sub_id":"101","register_pk":"105129","name":"神明神社本殿","kana":"しんめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南清水町174","lat":35.14254065,"lng":136.21604475,"geo_status":"db","era":"寛政2","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"25 － 0231","desc":"三間社春日造の社殿建築。身舎柱は欅材で間口３間奥行２間の一室とし，正側面に縁を巡らし，正面には１間の向唐破風を設ける。組物は出三斗とし，軒は二軒繁垂木，背面妻は豕扠首組，屋根は銅板葺である。町内唯一の三間社春日造の近世遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004139"},{"id":"00003246","register_sub_id":"101","register_pk":"104236","name":"杉尾神社本殿","kana":"すぎおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町杉山73","lat":34.84730366,"lng":136.01698767,"geo_status":"db","era":"宝永4","year":1707,"year_source":"db","year_min":1707,"year_max":1707,"year_label":null,"structure":"木造平屋建、柿葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0206","desc":"一間社流造の社殿で，覆屋に収められている。棟札より宝永４年の建築であることが知られる。木柄が太く，細部も大ぶりな点に特徴があり，現状では彩色部分と白木の部材が混在している。滋賀県下に多数存在する一間社社殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003246"},{"id":"00006404","register_sub_id":"101","register_pk":"107387","name":"スミス記念堂（旧須美壽記念禮拜堂）","kana":"すみすきねんどう（きゅうすみすきねんれいはいどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市本町3-58","lat":35.27388952,"lng":136.24930917,"geo_status":"db","era":"昭和6／平成19移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"25 － 0254","desc":"入母屋造妻入桟瓦葺で、正面に唐破風造銅板葺の１間向拝を付けるもと教会礼拝堂。正面３間に桟唐戸をたて、側面前寄り３間は窓を設ける。和風を基調としながら、十字架や葡萄、鳩などをモチーフとした彫刻や金具を施す。昭和初期の和風教会堂として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006404"},{"id":"00002399","register_sub_id":"101","register_pk":"103389","name":"禅明坊門","kana":"ぜんめいぼうもん","category":"宗教","subcategory":"その他工作","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080395,"lng":135.868073,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0168","desc":"１間１戸高麗門の形式で，親柱を上部に延ばして直接棟木を受け，軒は疎垂木，屋根は桟瓦葺とする。親柱を結ぶ内法虹梁と木鼻に施した絵様や，親柱足元の八艘飾などが，意匠の見所となっている。参道の北側の東端に位置し，参道らしい連続性を保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002399"},{"id":"00002397","register_sub_id":"101","register_pk":"103387","name":"禅林坊門","kana":"ぜんりんぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080544,"lng":135.867416,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0166","desc":"西教寺の塔頭は，本堂前より東の琵琶湖に向かって延びる参道南にある。１間１戸薬医門の形式で，軒は疎垂木，屋根は桟瓦葺，妻飾は蟇股とする。木鼻や蟇股などの絵様細部に江戸末期らしい造形がある。北にある實成坊と対になって，参道空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002397"},{"id":"00003105","register_sub_id":"101","register_pk":"104095","name":"宗林寺本堂","kana":"そうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南花沢町588","lat":35.125118,"lng":136.258286,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0201","desc":"江戸時代末期に建てられた入母屋造，桟瓦葺の浄土真宗本堂。比較的小規模ながら，内外陣境の支輪付出組組物の構えや虹梁の彫刻など，細部は本格的。内陣の仏壇や余間後方の部屋に改造を受けているが，なお当初の形式を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003105"},{"id":"00003247","register_sub_id":"101","register_pk":"104237","name":"高宮神社本殿","kana":"たかみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町多羅尾646","lat":34.813515,"lng":136.038162,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0207","desc":"一間社流造，檜皮葺の社殿。棟札より安政６年の新築で，近江蒲生郡八幡町の名工高木作右衛門が棟梁を努めたことが知られる。同種の社殿としてはやや大きく，身舎を内陣・下陣に分けるなど形式を整えている。中規模一間社の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003247"},{"id":"00012955","register_sub_id":"101","register_pk":"368035","name":"太郎坊宮阿賀神社一の鳥居","kana":"たろうぼうぐうあがじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町780-2","lat":35.11720278,"lng":136.18268889,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、間口5.4m","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 438","desc":"八風街道沿いにある参道入口に南面して建つ。石造の明神鳥居で、足元径0・6メートルの内転び円柱に貫を通し、反りのある島木笠木を載せる。北に延びる参道の先に赤神山を臨み、神社の入口を象徴するとともに参道景観を彩る大鳥居として参拝者に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012955"},{"id":"00012947","register_sub_id":"101","register_pk":"368027","name":"太郎坊宮阿賀神社永安殿","kana":"たろうぼうぐうあがじんじゃえいあんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11801389,"lng":136.18184722,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、銅板葺、建築面積43㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 430","desc":"拝殿南側の崖下に東面して建つ神楽演奏所兼社務所。入母屋造銅板葺妻入の二階建で、参道石段に面する正面に唐破風玄関を付す。一階に大座敷、二階に2室を配し、二階の北西二面に掃出しの縁を廻して拝殿に接続する。近代に発展した境内の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012947"},{"id":"00012952","register_sub_id":"101","register_pk":"368032","name":"太郎坊宮阿賀神社絵馬殿","kana":"たろうぼうぐうあがじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11775278,"lng":136.18209167,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 435","desc":"境内中心部南方の境内最下部にあり、参道石段に東面して建つ。切妻造桟瓦葺、桁行3間梁間2間の1間毎に柱を立てる。組物は舟肘木、妻飾は叉首組、一軒疎垂木で化粧屋根裏とする。奈良県技師・岸熊吉の設計による、簡明かつ整然としたつくりの近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012952"},{"id":"00012946","register_sub_id":"101","register_pk":"368026","name":"太郎坊宮阿賀神社神楽殿","kana":"たろうぼうぐうあがじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11802778,"lng":136.18168889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 429","desc":"拝殿背面に東面して建つ。入母屋造銅板葺妻入で、正側面に縁を廻す。正面は開放とし、側面2間に半蔀、背面3間の中央間に板扉を備える。内部は板敷、折上小組格天井の一室で、組物は平三斗、一軒扇垂木である。拝殿と一体で社頭景観の中核を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012946"},{"id":"00012949","register_sub_id":"101","register_pk":"368029","name":"太郎坊宮阿賀神社祭器庫","kana":"たろうぼうぐうあがじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809167,"lng":136.18213889,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 432","desc":"参道石段を挟んで長楽殿に対面して建つ。置屋根形式の切妻造妻入、土蔵造二階建で、西面に扉口を設けて吹放し下屋を付す。外壁は漆喰塗、腰縦板張で、鉢巻二段を廻し、西南二面に小窓を穿つ。立体的に構成された参道石段沿いの境内景観の添景となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012949"},{"id":"00012942","register_sub_id":"101","register_pk":"368022","name":"太郎坊宮阿賀神社参拝所","kana":"たろうぼうぐうあがじんじゃさんぱいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11805,"lng":136.18145,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 425","desc":"本殿前に東面して建つ。入母屋造銅板葺の渡殿を核として正面中央に切妻造の向拝を設け、背面に切妻造吹放しの幣殿を出して接続する本殿の側背面に下屋状の屋根を廻す。本殿と一体化した複雑な屋根を形成し、山腹に広がる境内景観の象徴的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012942"},{"id":"00012944","register_sub_id":"101","register_pk":"368024","name":"太郎坊宮阿賀神社授与所","kana":"たろうぼうぐうあがじんじゃじゅよしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809722,"lng":136.181525,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積2.9㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 427","desc":"参拝所の正面石段下の北脇に南面して建つ。入母屋造銅板葺の妻を正面として、背面を岩壁の窪みに入れ込む。正面間口は楣を通して硝子窓4枚を入れ、西側面に出入口を設ける。壁は簓子下見板張とする。岩峰中腹に形成された独特な社頭景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012944"},{"id":"00012954","register_sub_id":"101","register_pk":"368034","name":"太郎坊宮阿賀神社中門","kana":"たろうぼうぐうあがじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2251","lat":35.11752778,"lng":136.18240556,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、面積8.6㎡","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 437","desc":"絵馬殿南方の参道石段下半部の踊場に建つ。総花崗石造、四方吹放しの長方形平面で、切妻造妻入、反りのある流し石板葺である。軸部は内転びの円柱を木鼻付の貫と梁桁でつなぎ、貫上中央に蟇股を置く。不動明王拝所と同じく、昭和初期の石工技術の高さを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012954"},{"id":"00012948","register_sub_id":"101","register_pk":"368028","name":"太郎坊宮阿賀神社長楽殿","kana":"たろうぼうぐうあがじんじゃちょうらくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11807222,"lng":136.18177778,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造及び鉄筋コンクリート造平屋地下一階建、瓦葺及び銅板葺、建築面積154㎡、階段棟付","structure_material":"木造及び鉄筋コンクリート造平屋地下一階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 431","desc":"永安殿南側の崖下に東面して建つ集会施設。入母屋造桟瓦葺妻入の平屋建で、参道石段側の正面に唐破風玄関を設け、東北隅に永安殿へ渡る階段棟を附属する。内部は格天井の3室を並べ、地下に炊事場と浴室を設ける。近代に発展した境内景観の象徴的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012948"},{"id":"00012950","register_sub_id":"101","register_pk":"368030","name":"太郎坊宮阿賀神社手水舎","kana":"たろうぼうぐうあがじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809722,"lng":136.18195278,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造、銅板葺、面積5.0㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 433","desc":"永安殿東側にある岩棚北端に南面して建つ。切妻造銅板葺、四方吹放しの長方形平面で、西北隅に手水石を据え、格天井を張る。軸部は内転びの角柱頂部を木鼻付の貫で固める。組物は舟肘木、中備蟇股で、細部を復古調の意匠とし、神域の入口を厳かに演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012950"},{"id":"00012951","register_sub_id":"101","register_pk":"368031","name":"太郎坊宮阿賀神社銅鳥居","kana":"たろうぼうぐうあがじんじゃどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和中","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11816389,"lng":136.18176389,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造、間口1.8m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 434","desc":"拝殿の北側にあり、本殿に通じる岩峰の裂け目の前に東面して建つ。木造で、円柱に貫を通し、反りのない島木笠木を重ねる八幡鳥居形式とし、全体を銅板で包む。神域の入口を明示するとともに古来の磐境信仰の中枢を象徴する構造物として存在感を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012951"},{"id":"00012945","register_sub_id":"101","register_pk":"368025","name":"太郎坊宮阿賀神社拝殿","kana":"たろうぼうぐうあがじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11807222,"lng":136.18177778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 428","desc":"境内中心部の岩峰下端に東面して建つ。桁行3間梁間3間、入母屋造銅板葺妻入で、四周に縁を廻す。四方吹放し舞殿形式で、格天井を張る。組物は三斗拳鼻付、中備は各面中央間に蟇股、一軒扇垂木。当社で希少な近世社殿で、伝統的な境内構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012945"},{"id":"00012943","register_sub_id":"101","register_pk":"368023","name":"太郎坊宮阿賀神社舞台","kana":"たろうぼうぐうあがじんじゃぶたい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11801944,"lng":136.18155,"geo_status":"db","era":"明治13年／昭和23年改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造、面積31㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 426","desc":"参拝所前面の岩棚南側に張出す露天の舞台。桁行4間梁間3間、懸造で、貫6段を通して軸部を固めて梁桁を組む。上面の床は鉄筋コンクリート造で、東西南三面に擬宝珠高欄を廻す。本殿前の広場を形成し、急峻な岩肌に立地する独特な社頭景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012943"},{"id":"00012953","register_sub_id":"101","register_pk":"368033","name":"太郎坊宮阿賀神社不動明王拝所","kana":"たろうぼうぐうあがじんじゃふどうみょうおうはいしょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11772778,"lng":136.18185,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、面積4.9㎡","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 436","desc":"絵馬殿西側にある不動明王の祠の前に建つ。総花崗石造、方一間吹放しで、軸部は内転び角柱を貫と梁桁でつなぎ、束で棟木を受ける。屋根は東西棟の切妻造、反りのある流し石板葺である。大棟や鬼瓦等の細部も花崗石で精巧につくり、高度な石工技術をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012953"},{"id":"00012941","register_sub_id":"101","register_pk":"368021","name":"太郎坊宮阿賀神社本殿","kana":"たろうぼうぐうあがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11805833,"lng":136.18138333,"geo_status":"db","era":"宝暦3年（1753）／大正13年改修","year":1753,"year_source":"db","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 424","desc":"東近江市街西方の赤神山にある神社。本殿は岩峰南腹に東面して建つ一間社入母屋造銅板葺、正面千鳥破風、向拝軒唐破風付で、正側面に縁を廻す。二手先詰組に中備蟇股を加え、頭貫木鼻の霊獣や手挟の菊花彫刻、台輪木鼻の繰形など、要所に丁寧な装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012941"},{"id":"00002636","register_sub_id":"101","register_pk":"103626","name":"東方寺本堂","kana":"とうほうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市平松町471","lat":35.14502872,"lng":136.25004752,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0187","desc":"町内唯一の天台宗寺院の本堂。桁行梁間各３間，向拝１間，入母屋造，桟瓦葺で，方柱上に平三斗組物を載せ側桁を受け１軒繁垂木の軒を支える。内部は畳敷，小組格天井で，奥１間通りに丸柱を立て凸型に仏壇を構える。明治期の小規模密教本堂の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002636"},{"id":"00002398","register_sub_id":"101","register_pk":"103388","name":"徳乗坊門","kana":"とくじょうぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080517,"lng":135.867783,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0167","desc":"形式は１間１戸の薬医門であるが，軒は疎垂木・木舞打で，起りのある桟瓦葺の屋根を架け，冠木を丸太状の材とするなど，数寄屋風の意匠が取り込まれており，近代和風の造形と思われる。参道の北側，實成坊と禅明坊の間に位置し，参道空間に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002398"},{"id":"00003104","register_sub_id":"101","register_pk":"104094","name":"西福寺本堂","kana":"にしふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市平柳町1676","lat":35.14843,"lng":136.26506,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0200","desc":"江戸時代末期に建てられた入母屋造，本瓦葺の浄土宗本堂。鬼瓦には慶応元年（１８６５）の銘がある。梁間を前後に分け，前半部を外陣，後半部を桁行に３分し，内陣と両脇陣をとる浄土宗仏堂の典型的な平面。各所にあしらった彫刻が時代を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003104"},{"id":"00003262","register_sub_id":"101","register_pk":"104252","name":"日本基督教団今津教会（旧今津基督教会館）","kana":"にほんきりすときょうだんいまづきょうかい（きゅういまづきりすときょうかいかん）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市今津町今津1650-1","lat":35.402676,"lng":136.035049,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡、塔屋付","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0222","desc":"木造，平屋建，外壁モルタル塗，瓦葺（元スレート葺）で，ほぼ正方形の聖堂を中心に，北に講壇，南に玄関ホールを置き，４隅に事務室，図書室などを配す。正面に大きな妻面を見せ，頂部に塔屋をあげた明朗で印象的な外観をもつ。ヴォーリズ建築事務所の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003262"},{"id":"00009323","register_sub_id":"101","register_pk":"194116","name":"日本基督教団近江金田教会礼拝堂","kana":"にほんきりすときょうだんおうみかねだきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"滋賀県","address":"滋賀県近江八幡市鷹飼町1575","lat":35.12446085,"lng":136.10215702,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、スレート葺、建築面積95㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0321","desc":"木造二階建、建築面積九五平方メートル、切妻造スレート葺。南西に鐘楼を建て、南妻の切妻造玄関入口をアーチ形とする。一階は集会室、二階は単廊式の会堂でキングポスト・トラスを現す。外壁モルタル塗で、一階の引違窓、二階の上下窓とも簡素な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009323"},{"id":"00001077","register_sub_id":"101","register_pk":"102067","name":"日本基督教団堅田教会","kana":"にほんきりすときょうだんかたたきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田3-18-6","lat":35.11412573,"lng":135.91620256,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造２階建，鉄板葺一部スレート葺，建築面積178㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"25 － 0109","desc":"大津市の北方，堅田地区に建つ教会で，ヴォーリズ建築事務所の設計になる。単廊式の会堂で，会堂部にはキングポストの簡潔な小屋組を顕わす。正面中央上部にチューダーアーチの４連窓を開け，右手にトンガリ屋根の角塔をあげて特徴的な外観を造りあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001077"},{"id":"00001078","register_sub_id":"101","register_pk":"132576","name":"日本基督教団堅田教会塀","kana":"にほんきりすときょうだんかたたきょうかいへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田3-18-6","lat":35.11392899,"lng":135.91616977,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造，延長15.5m","structure_material":"煉瓦造","registered":"1999.02.17(平成11.02.17)","register_no":"25 － 0110","desc":"堅田の波止場に通じる街路に面する。赤煉瓦１枚厚，長手積みの塀で，高さは煉瓦１２段と程良い高さに押さえられおり，会堂玄関前に教会らしい開放的な空間を造りだしている。最上段は煉瓦の長手面を下にし，４５度振って笠石的扱いとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001078"},{"id":"00001714","register_sub_id":"101","register_pk":"102704","name":"日本キリスト教団水口教会門柱","kana":"にほんきりすときょうだんみなくちきょうかいもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町城東3-21","lat":34.97169893,"lng":136.16856876,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造、高さ1.5m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0134","desc":"礼拝堂玄関に対応した敷地南辺に位置する。煉瓦２枚半角で、みかけ煉瓦１９段に積み、最上部は煉瓦の長手面を下にして積んで納める。門柱の左右には、５段積程度の低い煉瓦塀が取り付き、柵などで開放的に囲っていたことがうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001714"},{"id":"00001713","register_sub_id":"101","register_pk":"102703","name":"日本キリスト教団水口教会礼拝堂","kana":"にほんきりすときょうだんみなくちきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町城東3-21","lat":34.971882,"lng":136.168594,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、スレート葺一部鉄板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0133","desc":"ヴォーリズ建築事務所設計になる簡素な教会堂建築。木造、平屋建で、南北棟を大棟としたラテン十字形の外郭をもつが、南妻面の東半に玄関を設け、東西方向の交差廊部を礼拝堂に充てている平面構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001713"},{"id":"00009499","register_sub_id":"101","register_pk":"194292","name":"橋本家住宅（旧正蔵坊）主屋","kana":"はしもとけじゅうたく（きゅうしょうぞうぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市小関町88","lat":35.00816188,"lng":135.85615139,"geo_status":"db","era":"正保元年／昭和前期・昭和後期改修","year":1644,"year_source":"db","year_min":1644,"year_max":1644,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0323","desc":"敷地中央に建つ。木造平屋建、建築面積一二六平方メートル、切妻造及び入母屋造桟瓦葺。南東側の八畳主室に二間幅の大ドコと付書院を付し、庭園に臨む三面に縁を廻らす。側廻りは柱上に舟肘木を載せ、垂木を疎らに配る。園城寺別所の坊として希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009499"},{"id":"00003245","register_sub_id":"101","register_pk":"104235","name":"日雲神社本殿","kana":"ひくもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町牧75","lat":34.90797811,"lng":136.08335662,"geo_status":"db","era":"元禄4","year":1691,"year_source":"db","year_min":1691,"year_max":1691,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0205","desc":"元禄４年の建築と伝える三間社流造，向拝１間の神社本殿。桁行３間梁間２間の身舎に１間幅の前室を設け，正側面に縁を廻らす。前室は前面中央間を引分戸とする他は斜格子嵌め殺しとする。近年金属板で仮葺されているが，当初の状況を良く伝える本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003245"},{"id":"00005281","register_sub_id":"101","register_pk":"106269","name":"火頭古神社本殿","kana":"ひずこじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市土山町猪鼻163","lat":34.92073569,"lng":136.31424476,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"25 － 0237","desc":"桁行０．９ｍ，梁間０．７ｍ規模，二軒繁垂木，檜皮葺の一間社流造。身舎は円柱，向拝は角柱とし，組物は連三斗として中備に蟇股を置く。正側面に縁と高欄を廻し，正面中央に木階段を付す。檜の良材を用い，形式や工法に古式を残し，彫刻も質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005281"},{"id":"00000795","register_sub_id":"101","register_pk":"101785","name":"百済寺本坊喜見院書院","kana":"ひゃくさいじほんぼうきけんいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市百済寺町323","lat":35.12686313,"lng":136.28891781,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積200㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0053","desc":"湖東三山のひとつ百済寺の本坊にあって，庭に面して建つ大型の入母屋造書院。平面は，仏間や書院の間などからなる２列６室の居室の２方に広縁を取り，四方に濡縁を張る。年代は新しいが，細部の造作とも伝統的な工法になる。設計・施工は大工の宮部太兵衛。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000795"},{"id":"00010830","register_sub_id":"101","register_pk":"201665","name":"日吉神社本殿","kana":"ひよしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町1097","lat":35.404755,"lng":136.253057,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積7.9㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0374","desc":"集落内の境内に西面して建ち、一間社切妻造、向拝一間、檜皮葺である。組物間を猿や霊獣の彫刻で埋める。正面小脇板や妻壁に配した植物や雲紋の彫刻、手挟や木鼻の透彫等、いずれも巧緻な施工で躍動感ある表現となる。湖北で活躍した大工宮部家の力量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010830"},{"id":"00010831","register_sub_id":"101","register_pk":"201666","name":"日吉神社門及び玉垣","kana":"ひよしじんじゃもんおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町1097","lat":35.404734,"lng":136.25299,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"門 木造、檜皮葺、間口1.8m 玉垣 木造、瓦葺、延長36m","structure_material":"門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0375","desc":"本殿西正面の門と本殿を囲む玉垣。薬医門形式の門は、切妻造で正面に軒唐破風を付け、正面上部や妻壁に植物や雲紋の華やかな彫刻を飾る。玉垣は北に潜りを開き、繰形付の持送で腕木を受けて桟瓦を葺く。内法は竪連子を廻らせる。本殿に劣らぬ装飾性を備えた門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010831"},{"id":"00015315","register_sub_id":"101","register_pk":"532439","name":"宝厳寺弁才天堂","kana":"ほうごんじべんざいてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市早崎町1664-3","lat":35.42145278,"lng":136.14328889,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積439㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"25 - 0522","desc":"竹生島にある真言宗寺院本堂。設計は乾兼松。桁行五間梁間五間、入母屋造檜皮葺の正面に千鳥破風を飾り四周裳階付き。前方に土間の礼堂、後方に内陣・脇陣を配す。内陣は柱を立ち登らせ組物は差肘木で小壁に飛天を描く。近代における復古的意匠の仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015315"},{"id":"00001777","register_sub_id":"101","register_pk":"102767","name":"宮部西薬師堂","kana":"みやべにしやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市宮部町1810、1811","lat":35.41946559,"lng":136.27449,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"25 － 0135","desc":"小規模な宝形造二重屋根の仏堂。平面は正方形で方２間の規模を持つ。初重は挿肘木，平行垂木，上重は出組，扇垂木とし，上下で外観に意匠的変化をつける。向拝組物間の彫物や手挟に見所を持つ。大工は棟札より隣町の西嶋繁右衛門であることが知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001777"},{"id":"00003244","register_sub_id":"101","register_pk":"104234","name":"妙感寺本堂（観音堂）","kana":"みょうかんじほんどう（かんのんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県湖南市三雲1758","lat":34.97560738,"lng":136.09630228,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0204","desc":"木造３間四方，入母屋造本瓦葺の堂宇。東面して平入とする。昭和１２年の建築で，設計は当時京都帝国大学の講師であった藤原義一が当たった。内部は板敷とし，正側面三方に濡縁を廻らす。禅宗様を基調とする本堂で，中世の趣を伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003244"},{"id":"00014624","register_sub_id":"101","register_pk":"515166","name":"明楽寺経蔵","kana":"みょうらくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50493611,"lng":136.22655,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0518","desc":"本堂南に建つ土蔵造の経蔵。宝形造桟瓦葺で露盤宝珠を飾り、北面に切妻造銅板葺向拝を付す。切石積基壇に建ち、外壁は漆喰仕上で東西に火灯窓を開ける。内部は一室で虹梁形火打梁を架け、北半を土間、南半板敷とし、貼付紙の天井に飛天を描いて荘厳する経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014624"},{"id":"00014622","register_sub_id":"101","register_pk":"515164","name":"明楽寺庫裏","kana":"みょうらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町937他","lat":35.50533333,"lng":136.2262,"geo_status":"db","era":"安永年間（1772-1781）","year":1776,"year_source":"estimated","year_min":1772,"year_max":1781,"year_label":"安永年間（1772-1781）","structure":"木造平屋建、瓦葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0516","desc":"本堂の北西に建つ庫裏。平屋建切妻造平入桟瓦葺で南面中央に式台玄関を設ける。内部は棟通りで南北二列に分け、南列は西に梁組を見せる吹抜の土間、東に平書院付の床を構えた三間続きの座敷とする。軸部は木太く、風格を備え、歴史的な伽藍を構成する庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014622"},{"id":"00014626","register_sub_id":"101","register_pk":"515168","name":"明楽寺山門","kana":"みょうらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.5051,"lng":136.22612778,"geo_status":"db","era":"文化4年（1807）","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造、瓦葺、間口5.1m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0520","desc":"本堂の西方で参道に開く一間一戸の四脚門。切妻造桟瓦葺で、本柱は円柱、袖柱は角柱とし、腰貫、飛貫、頭貫で固める。組物は支輪を備えた出組、軒は二軒繁垂木とする。飛貫と頭貫の木鼻を彫刻で飾った華やかな山門で、伽藍と宿場の町並みの歴史的景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014626"}];
